window.HADITH_DATA['muslim'][52]=[[7045,7045,"2785","আবূ বাকর ইবনু ইসহাক (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) এর সূত্রে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে বর্ণিত। তিনি বলেছেন, কিয়ামতের ময়দানে মোটা-তাজা লোক উপস্থিত হবে, কিন্তু আল্লাহর নিকট তার ওযন মশার ডানার ন্যায়ও হবে না। তোমরা পড়ে নাও \"কিয়ামতের দিন আমি তাদের জন্য কোন পরিমাপক স্থাপন করব না\"- (সূরা আল কাহফ ১৮ঃ ১০৫)। (ইসলামিক ফাউন্ডেশন ৬৭৮৮, ইসলামিক সেন্টার)","حَدَّثَنِي أَبُو بَكْرِ بْنُ إِسْحَاقَ، حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنِي الْمُغِيرَةُ، - يَعْنِي الْحِزَامِيَّ - عَنْ أَبِي الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ إِنَّهُ لَيَأْتِي الرَّجُلُ الْعَظِيمُ السَّمِينُ يَوْمَ الْقِيَامَةِ لاَ يَزِنُ عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ اقْرَءُوا ‏{‏ فَلاَ نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا‏}‏ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:A bulky person would be brought on the Day of judgment and he would not carry the weight to the eye of Allah equal even to that of a gnat. Nor shall We set up a balance for them on the Day of Resurrection\" (xviii)","",""],[7046,7046,"2786.01","আহমাদ ইবনু আবদুল্লাহ ইবনু ইউনুস (রহঃ) ..... আবদুল্লাহ ইবনু মাসউদ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, একদা এক ইয়াহুদী পাদরী নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর কাছে এসে সম্বোধন করে বলল, হে মুহাম্মাদ! অথবা (বলল) হে আবুল কাসিম \"কিয়ামতের দিন আল্লাহ তা’আলা আকাশমণ্ডলীকে এক আঙ্গুলে, জমিনসমূহকে এক আঙ্গুলে, পাহাড় ও গাছপালাকে এক আঙ্গুলে; পানি ও মাটি এক আঙ্গুলে এবং সকল প্রকার সৃষ্টিকে এক আঙ্গুলে তুলে ধরবেন। তারপর এগুলো দুলিয়ে বলবেন, আমিই বাদশাহ, আমিই অধিপতি।\" পাদরীর কথা শুনে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বিস্ময়ের সাথে তার সত্যায়ন স্বরূপ হাসলেন। অতঃপর তিনি পাঠ করলেনঃ (অর্থ) \"তারা আল্লাহর যথোপযুক্ত সম্মান প্রদর্শন করেনি। কিয়ামতের দিন সমস্ত পৃথিবী তার হাতের মুষ্টিতে এবং আকাশমণ্ডলী থাকবে তার ডান হাতের মুঠোয়। পবিত্র ও মহান তিনি, তারা যাকে অংশীদার স্থাপন করে, তিনি তার থেকে অনেক উর্ধ্বে\"- (সূরা আয যুমার ৩৯ঃ ৬৭)। (ইসলামিক ফাউন্ডেশন ৬৭৮৯ ইসলামিক সেন্টার)","حَدَّثَنَا أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يُونُسَ، حَدَّثَنَا فُضَيْلٌ، - يَعْنِي ابْنَ عِيَاضٍ - عَنْ مَنْصُورٍ، عَنْ إِبْرَاهِيمَ، عَنْ عَبِيدَةَ السَّلْمَانِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ جَاءَ حَبْرٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ يَا مُحَمَّدُ أَوْ يَا أَبَا الْقَاسِمِ إِنَّ اللَّهَ تَعَالَى يُمْسِكُ السَّمَوَاتِ يَوْمَ الْقِيَامَةِ عَلَى إِصْبَعٍ وَالأَرَضِينَ عَلَى إِصْبَعٍ وَالْجِبَالَ وَالشَّجَرَ عَلَى إِصْبَعٍ وَالْمَاءَ وَالثَّرَى عَلَى إِصْبَعٍ وَسَائِرَ الْخَلْقِ عَلَى إِصْبَعٍ ثُمَّ يَهُزُّهُنَّ فَيَقُولُ أَنَا الْمَلِكُ أَنَا الْمَلِكُ ‏.‏ فَضَحِكَ رَسُولُ اللَّهِ صلى الله عليه وسلم تَعَجُّبًا مِمَّا قَالَ الْحَبْرُ تَصْدِيقًا لَهُ ثُمَّ قَرَأَ ‏{‏ وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ‏}‏","Abdullah b. Mas'ud reported that a Jewish scholar came to Allah's Apostle (may peace he upon him) and said:Muhammad, or Abu al-Qasim, verily, Allah, the Exalted and Glorious would carry the Heavens on the Day of Judgment upon one finger and earths upon one finger and the mountains and trees upon one finger and the ocean and moist earth upon one finger, and in fact the whole of the creation upon one finger, and then He would stir them and say: I am your Lord, I am your Lord. Thereupon Allah's Messenger (ﷺ) smiled testifying what that scholar had said. He then recited this verse:\" And they honour not Allah with the honour due to Him; and the whole earth will be in His grip on the Day of Resurrection and the heaven rolled up in His right hand. Glory be to Him I and highly Exalted is He above what they associate (with Him)\" (Az-Zumar:)","আহমাদ ইবনু আবদুল্লাহ ইবনু ইউনুস (রহঃ) ..... আবদুল্লাহ ইবনু মাসউদ (রাযিঃ",""],[7047,7047,"2786.02","(…) উসমান ইবনু আবু শাইবাহ ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... মানসূর (রহঃ) থেকে উক্ত সূত্রে বলেছেন যে, জনৈক ইয়াহুদী পাদরী লোক রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর নিকট আসলো, পরবর্তী অংশ ফুযায়ল এর হাদীসের অনুরূপ। তবে তিনি এগুলো দুলিয়েছেন কথাটির উল্লেখ করেননি। এতে এ-ও রয়েছে যে, তার কথায় বিস্মিত হয়ে তার সত্যায়নে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লামকে আমি এমনভাবে হাসতে দেখেছি যে, তার মাড়ির দাঁত মুবারক প্রকাশিত হয়ে গিয়েছিল। তারপর রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তিলাওয়াত করলেন, (অর্থ) \"তারা আল্লাহর যথোপযুক্ত সম্মান প্রদর্শন করেনি\" ..... পূর্ণ আয়াত তিলাওয়াত করেন। (ইসলামিক ফাউন্ডেশন ৬৭৯০, ইসলামিক সেন্টার)","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، كِلاَهُمَا عَنْ جَرِيرٍ، عَنْ مَنْصُورٍ، بِهَذَا الإِسْنَادِ قَالَ جَاءَ حَبْرٌ مِنَ الْيَهُودِ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم بِمِثْلِ حَدِيثِ فُضَيْلٍ وَلَمْ يَذْكُرْ ثُمَّ يَهُزُّهُنَّ ‏.‏ وَقَالَ فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ تَعَجُّبًا لِمَا قَالَ تَصْدِيقًا لَهُ ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ ‏{‏ وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ‏}‏ ‏\"‏ ‏.‏ وَتَلاَ الآيَةَ ‏.‏","This hadlth has been narrated on the authority of Mansur with the same chain of truemittm (and the words are):A Jew scholar came to Allah's Messenger (ﷺ). The rest of the hadith is the same, but there is no mention of\" then He would stir them.\" But there is this addition:\" I saw Allah's Messengcr (ﷺ) smiling so much that his front teeth appeared and testifying him (th Jew scholar) ; then Allah's Messenger (ﷺ) recited the verse:\" And they honour not Allah with the honour due to Him\" (xxxix)","",""],[7048,7048,"2786.03","উমর ইবনু হাফস ইবনু গিয়াস (রহঃ) .... ‘আবদুল্লাহ (রাযিঃ) থেকে বর্ণিত। আহলে কিতাবদের জনৈক লোক রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর কাছে এসে বলল, হে আবুল কাসিম! আল্লাহ তা’আলা আকাশমণ্ডলী এক আঙ্গুলে, ভূমণ্ডল এক আঙ্গুলে, গাছপালা ও আর্দ্র মাটি এক আঙ্গুলে এবং সকল সৃষ্টি এক আঙ্গুলে তুলে ধরবেন। এরপর তিনি বলবেন, আমিই বাদশাহ্, আমিই রাজা। রাবী বলেন, তখন আমি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে এমনভাবে হাসতে দেখলাম যে, তার মাড়ি মুবারকের দাঁতগুলো প্রকাশ পেলো। এরপর তিলাওয়াত করলেন, (অর্থ) \"তারা আল্লাহর যথোপযুক্ত সম্মান প্রদর্শন করেনি।\" (ইসলামিক ফাউন্ডেশন ৬৭৯১, ইসলামিক সেন্টার)","حَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، قَالَ سَمِعْتُ إِبْرَاهِيمَ، يَقُولُ سَمِعْتُ عَلْقَمَةَ، يَقُولُ قَالَ عَبْدُ اللَّهِ جَاءَ رَجُلٌ مِنْ أَهْلِ الْكِتَابِ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا أَبَا الْقَاسِمِ إِنَّ اللَّهَ يُمْسِكُ السَّمَوَاتِ عَلَى إِصْبَعٍ وَالأَرَضِينَ عَلَى إِصْبَعٍ وَالشَّجَرَ وَالثَّرَى عَلَى إِصْبَعٍ وَالْخَلاَئِقَ عَلَى إِصْبَعٍ ثُمَّ يَقُولُ أَنَا الْمَلِكُ أَنَا الْمَلِكُ ‏.‏ قَالَ فَرَأَيْتُ النَّبِيَّ صلى الله عليه وسلم ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ ثُمَّ قَرَأَ ‏{‏ وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ‏}‏","Abdullah reported that a person from the People of the Book came to Allah's Apostle (may peace he upon him) and said:Abu al-Qasim, verily, Allah holds the Heavens upon one finger and the earths upon one finger and the trees and moist earth upon one finger and in fact the whole of the creation upon one finger and then say: I am the King. I am the King. And he (the narrator) further said: I saw Allah's Messenger (ﷺ) smiling until his front teeth became visible and then he recited the verse: \"And they measure not the power of Allah with His true measure\" (39:)","উমর ইবনু হাফস ইবনু গিয়াস (রহঃ) .... ‘আবদুল্লাহ (রাযিঃ",""],[7049,7049,"2786.04","আবু বকর ইবনু আবূ শাইবাহ, আবু কুরায়ব, ইসহাক ইবনু ইবরাহীম, আলী ইবনু খাশরাম ও উসমান ইবনু আবূ শাইবাহ (রহঃ) ... আ'মাশ (রহঃ) এর সূত্রে উক্ত সানাদে বর্ণনা করেছেন। তবে তাদের সকলের বর্ণনাতেই রয়েছে যে, বৃক্ষরাজি এক আঙ্গুলে এবং আর্দ্র মাটি এক আঙ্গুলো। তবে জারীর এর হাদীসে \"সকল প্রকার সৃষ্টি এক আঙ্গুলে\" কথাটি উল্লেখ নেই। অবশ্য তার হাদীসে \"পাহাড়সমূহ এক আঙ্গুলে\" কথাটি রয়েছে। জারীর (রাযিঃ) এর হাদীসে বর্ধিত রয়েছে যে, তার কথায় অবাক হয়ে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে সমর্থন করেন। (ইসলামিক ফাউন্ডেশন ৬৭৯২, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ قَالاَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، ح وَحَدَّثَنَا إِسْحَاقُ، بْنُ إِبْرَاهِيمَ وَعَلِيُّ بْنُ خَشْرَمٍ قَالاَ أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، ح وَحَدَّثَنَا عُثْمَانُ بْنُ أَبِي، شَيْبَةَ حَدَّثَنَا جَرِيرٌ، كُلُّهُمْ عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ غَيْرَ أَنَّ فِي، حَدِيثِهِمْ جَمِيعًا وَالشَّجَرَ عَلَى إِصْبَعٍ وَالثَّرَى عَلَى إِصْبَعٍ وَلَيْسَ فِي حَدِيثِ جَرِيرٍ وَالْخَلاَئِقَ عَلَى إِصْبَعٍ ‏.‏ وَلَكِنْ فِي حَدِيثِهِ وَالْجِبَالَ عَلَى إِصْبَعٍ ‏.‏ وَزَادَ فِي حَدِيثِ جَرِيرٍ تَصْدِيقًا لَهُ تَعَجُّبًا لِمَا قَالَ ‏.‏","This hadith has been narrated on the authority of A'mash with the same chain of transmitters but with a slight variation of wording","",""],[7050,7050,"2787","হারমালাহ্ ইবনু ইয়াহইয়া (রহঃ) ...... আবু হুরাইরাহ্ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ কিয়ামতের দিন আল্লাহ তা’আলা সারা পৃথিবী তার হাতের মুষ্টিতে নিয়ে নিবেন এবং আকাশমণ্ডলী ভাঁজ করে তার ডান হাতের মুঠোয় নিবেন। তারপর তিনি বলবেন, “আমিই বাদশাহ্। পৃথিবীর বাদশাহগণ কোথায়?” (ইসলামিক ফাউন্ডেশন ৬৭৯৩, ইসলামিক সেন্টার)","حَدَّثَنِي حَرْمَلَةُ بْنُ يَحْيَى، أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، حَدَّثَنِي ابْنُ الْمُسَيَّبِ، أَنَّ أَبَا هُرَيْرَةَ، كَانَ يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ يَقْبِضُ اللَّهُ تَبَارَكَ وَتَعَالَى الأَرْضَ يَوْمَ الْقِيَامَةِ وَيَطْوِي السَّمَاءَ بِيَمِينِهِ ثُمَّ يَقُولُ أَنَا الْمَلِكُ أَيْنَ مُلُوكُ الأَرْضِ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Apostle (ﷺ) as saying:Allah, the Exalted and Glorious, will take in His grip the Earth on the Day of Judgment and He would roll up the sky in His right hand and would say: I am the Lord; where are the sovereigns of the world?","হারমালাহ্ ইবনু ইয়াহইয়া (রহঃ) ...... আবু হুরাইরাহ্ (রাযিঃ",""],[7051,7051,"2788.01","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... ‘আবদুল্লাহ ইবনু উমর (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ কিয়ামতের দিন আল্লাহ তা’আলা আকাশমণ্ডলী পেচিয়ে নিবেন। তারপর তিনি আকাশমণ্ডলীকে ডান হস্তে ধরে বলবেন, আমিই বাদশাহ। কোথায় শক্তিশালী লোকেরা! কোথায় অহংকারীরা? এরপর তিনি বাম হস্তে গোটা পৃথিবী গুটিয়ে নিবেন এবং বলবেন, আমিই বাদশাহ। কোথায় অত্যাচারী লোকেরা, কোথায় বড়ত্ব প্রদর্শনকারীরা? (ইসলামিক ফাউন্ডেশন ৬৭৯৪, ইসলামিক সেন্টার)","وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ عُمَرَ بْنِ حَمْزَةَ، عَنْ سَالِمِ، بْنِ عَبْدِ اللَّهِ أَخْبَرَنِي عَبْدُ اللَّهِ بْنُ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ يَطْوِي اللَّهُ عَزَّ وَجَلَّ السَّمَوَاتِ يَوْمَ الْقِيَامَةِ ثُمَّ يَأْخُذُهُنَّ بِيَدِهِ الْيُمْنَى ثُمَّ يَقُولُ أَنَا الْمَلِكُ أَيْنَ الْجَبَّارُونَ أَيْنَ الْمُتَكَبِّرُونَ ثُمَّ يَطْوِي الأَرَضِينَ بِشِمَالِهِ ثُمَّ يَقُولُ أَنَا الْمَلِكُ أَيْنَ الْجَبَّارُونَ أَيْنَ الْمُتَكَبِّرُونَ ‏\"‏ ‏.‏","Abdullah b. 'Umar reported Allah's Messenger (ﷺ) saying:Allah, the Exalted and Glorious, would fold the Heavens on the Day of Judgment and then He would place them on His right hand and say: I am the Lord; where are the haughty and where are the proud (today)? He would fold the' earth (placing it) on the left hand and say: I am the Lord; where are the haughty and where are the proud (today)?","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... ‘আবদুল্লাহ ইবনু উমর (রাযিঃ",""],[7052,7052,"2788.02","সাঈদ ইবনু মানসূর (রহঃ) .... উবাইদুল্লাহ ইবনু মিকসাম (রহঃ) থেকে বর্ণিত। তিনি আবদুল্লাহ ইবনু উমর (রাযিঃ) এর দিকে তাকিয়ে থাকলেন, কিভাবে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর কথা বর্ণনা করছেন। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ আল্লাহ তা’আলা আকাশমণ্ডলী ও সারা পৃথিবী তার হস্তদ্বয়ে তুলে ধরবেন এবং বলবেন, আমিই আল্লাহ। তিনি স্বীয় আঙ্গুল সংকোচন ও সম্প্রসারণ করে বলবেন, আমিই বাদশাহ। আবদুল্লাহ ইবনু উমর (রাযিঃ) বলেন, এমনকি তখন আমি দেখতে পাচ্ছিলাম যে, মিম্বারের নিম্নাংশের কিছু দুলছিল। তখন আমি ভাবছিলাম, মিম্বারটি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে নিয়ে পড়ে যায় কিনা? (ইসলামিক ফাউন্ডেশন ৬৭৯৫, ইসলামিক সেন্টার)","حَدَّثَنَا سَعِيدُ بْنُ مَنْصُورٍ، حَدَّثَنَا يَعْقُوبُ، - يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ - حَدَّثَنِي أَبُو حَازِمٍ عَنْ عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ، أَنَّهُ نَظَرَ إِلَى عَبْدِ اللَّهِ بْنِ عُمَرَ كَيْفَ يَحْكِي رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ يَأْخُذُ اللَّهُ عَزَّ وَجَلَّ سَمَوَاتِهِ وَأَرَضِيهِ بِيَدَيْهِ فَيَقُولُ أَنَا اللَّهُ - وَيَقْبِضُ أَصَابِعَهُ وَيَبْسُطُهَا - أَنَا الْمَلِكُ ‏\"‏ حَتَّى نَظَرْتُ إِلَى الْمِنْبَرِ يَتَحَرَّكُ مِنْ أَسْفَلِ شَىْءٍ مِنْهُ حَتَّى إِنِّي لأَقُولُ أَسَاقِطٌ هُوَ بِرَسُولِ اللَّهِ صلى الله عليه وسلم","Abdullah b. Miqsam reported that he saw Abdullah b. Umar as he narrated Allah's Messenger (ﷺ) as saying:Allah, the Exalted and Glorious, would take in His hand His Heavens and His Earth, and would say: I am Allah. And He would clench His fingers and then would open them (and say): I am your Lord. I saw the pulpit in commotion from underneath because of something (vib-ating) there. And (I felt this commotion so much) that I said (to myself): It may not fall with Allah's Massenger (ﷺ) upon it","সাঈদ ইবনু মানসূর (রহঃ) .... উবাইদুল্লাহ ইবনু মিকসাম (রহঃ",""],[7053,7053,"2788.03","সাঈদ ইবনু মানুসূর (রহঃ) ..... ‘আবদুল্লাহ ইবনু উমর (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে মিম্বারের উপর এমন অবস্থায় দেখেছি যে, তিনি বলছেন, মহাপরাক্রমশালী সত্তা আকাশমণ্ডলী ও গোটা পৃথিবী স্বীয় হস্তদ্বয়ে তুলে ধরবেন। পরবর্তী অংশ ইয়াকুব এর হাদীসের অবিকল বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৭৯৬, ইসলামিক সেন্টার)","حَدَّثَنَا سَعِيدُ بْنُ مَنْصُورٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ، حَدَّثَنِي أَبِي، عَنْ عُبَيْدِ، اللَّهِ بْنِ مِقْسَمٍ عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى الْمِنْبَرِ وَهُوَ يَقُولُ ‏ \"‏ يَأْخُذُ الْجَبَّارُ عَزَّ وَجَلَّ سَمَوَاتِهِ وَأَرَضِيهِ بِيَدَيْهِ ‏\"‏ ‏.‏ ثُمَّ ذَكَرَ نَحْوَ حَدِيثِ يَعْقُوبَ ‏.‏","Abdullah b. Miqsam reported that 'Abdullah b. 'Umar reported:I saw Allah'h Messenger (ﷺ) upon the pulpit and he was saying that the Mighty Lord, the Exalted and Glorious would take hold of the Heavens and earth in His hand. The rest of the hadith is the same","সাঈদ ইবনু মানুসূর (রহঃ) ..... ‘আবদুল্লাহ ইবনু উমর (রাযিঃ",""],[7054,7054,"2789","সুরায়জ ইবনু ইউনুস ও হারূন ইবনু ‘আবদুল্লাহ (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমার হাত ধরে বললেন, আল্লাহ তা’আলা শনিবার দিন মাটি সৃষ্টি করেন এবং এতে পর্বত সৃষ্টি করেন রবিবার দিন। সোমবার দিন তিনি বৃক্ষরাজি সৃষ্টি করেন। মঙ্গলবার দিন তিনি বিপদাপদ সৃষ্টি করেন। তিনি নূর সৃষ্টি করেন বুধবার দিন। তিনি বৃহস্পতিবার দিন পৃথিবীতে পশু-পাখি ছড়িয়ে দেন এবং জুমুআর দিন আসরের পর জুমুআর দিনের শেষ মুহূর্তে অর্থাৎ আসর থেকে নিয়ে রাত পর্যন্ত সময়ের মধ্যবর্তী সময়ে সর্বশেষ মাখলুক আদম (আঃ) কে সৃষ্টি করেন। (ইসলামিক ফাউন্ডেশন ৬৭৯৭,ইসলামিক সেন্টার)","حَدَّثَنِي سُرَيْجُ بْنُ يُونُسَ، وَهَارُونُ بْنُ عَبْدِ اللَّهِ، قَالاَ حَدَّثَنَا حَجَّاجُ بْنُ مُحَمَّدٍ، قَالَ قَالَ ابْنُ جُرَيْجٍ أَخْبَرَنِي إِسْمَاعِيلُ بْنُ أُمَيَّةَ، عَنْ أَيُّوبَ بْنِ خَالِدٍ، عَنْ عَبْدِ اللَّهِ بْنِ رَافِعٍ، مَوْلَى أُمِّ سَلَمَةَ عَنْ أَبِي هُرَيْرَةَ، قَالَ أَخَذَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِيَدِي فَقَالَ ‏ \"‏ خَلَقَ اللَّهُ عَزَّ وَجَلَّ التُّرْبَةَ يَوْمَ السَّبْتِ وَخَلَقَ فِيهَا الْجِبَالَ يَوْمَ الأَحَدِ وَخَلَقَ الشَّجَرَ يَوْمَ الاِثْنَيْنِ وَخَلَقَ الْمَكْرُوهَ يَوْمَ الثُّلاَثَاءِ وَخَلَقَ النُّورَ يَوْمَ الأَرْبِعَاءِ وَبَثَّ فِيهَا الدَّوَابَّ يَوْمَ الْخَمِيسِ وَخَلَقَ آدَمَ عَلَيْهِ السَّلاَمُ بَعْدَ الْعَصْرِ مِنْ يَوْمِ الْجُمُعَةِ فِي آخِرِ الْخَلْقِ وَفِي آخِرِ سَاعَةٍ مِنْ سَاعَاتِ الْجُمُعَةِ فِيمَا بَيْنَ الْعَصْرِ إِلَى اللَّيْلِ ‏\"‏ ‏.‏ قَالَ إِبْرَاهِيمُ حَدَّثَنَا الْبِسْطَامِيُّ، - وَهُوَ الْحُسَيْنُ بْنُ عِيسَى - وَسَهْلُ بْنُ عَمَّارٍ وَإِبْرَاهِيمُ ابْنُ بِنْتِ حَفْصٍ وَغَيْرُهُمْ عَنْ حَجَّاجٍ، بِهَذَا الْحَدِيثِ ‏.‏","Abu Huraira reported that Allah's Messenger (ﷺ) took hold of my hands and said:Allah, the Exalted and Glorious, created the clay on Saturday and He created the mountains on Sunday and He created the trees on Monday and He created the things entailing labour on Tuesday and created light on Wednesday and He caused the animals to spread on Thursday and created Adam (peace be upon him) after 'Asr on Friday; the last creation at the last hour of the hours of Friday, i. e. between afternoon and night. This hadith is narrated through another chain of transmitters","সুরায়জ ইবনু ইউনুস ও হারূন ইবনু ‘আবদুল্লাহ (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ",""],[7055,7055,"2790","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... সাহল ইবনু সা’দ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ লোকেদেরকে কিয়ামতের দিন ময়দার রুটির ন্যায় (গোল) লালচে সাদা জমিনের উপরে জমায়েত করা হবে। সেখানে কারো কোন বিশেষ নিদর্শন মওজুদ থাকবে না। (ইসলামিক ফাউন্ডেশন ৬৭৯৮, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا خَالِدُ بْنُ مَخْلَدٍ، عَنْ مُحَمَّدِ بْنِ جَعْفَرِ بْنِ أَبِي، كَثِيرٍ حَدَّثَنِي أَبُو حَازِمِ بْنُ دِينَارٍ، عَنْ سَهْلِ بْنِ سَعْدٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ عَلَى أَرْضٍ بَيْضَاءَ عَفْرَاءَ كَقُرْصَةِ النَّقِيِّ لَيْسَ فِيهَا عَلَمٌ لأَحَدٍ ‏\"‏ ‏.‏","Sahl b. Sa'd reported that Allah's Messenger (ﷺ) said:The people will be assembled on the Day of Resurrection on a white plain with a reddish tinge like the loaf of white bread with no marks set up for anyone","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... সাহল ইবনু সা’দ (রাযিঃ",""],[7056,7056,"2791","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... আয়িশাহ্ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে আল্লাহর বাণীঃ (অর্থ) \"যেদিন এ পৃথিবী পরিবর্তিত হয়ে অন্য পৃথিবী হয়ে যাবে এবং আকাশমণ্ডলীও\"- (সূরা ইবরা-হীম ১৪ঃ ৪৮) সম্পর্কে প্রশ্ন করলাম, হে আল্লাহর রসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম! তবে সেদিন লোকেরা কোথায় থাকবে? তিনি বললেন, (জাহান্নামের উপরে নির্মিত) সেতুর উপরে অবস্থান করবে। (ইসলামিক ফাউন্ডেশন ৬৭৯৯, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ دَاوُدَ، عَنِ الشَّعْبِيِّ، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ، قَالَتْ سَأَلْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَنْ قَوْلِهِ عَزَّ وَجَلَّ ‏{‏ يَوْمَ تُبَدَّلُ الأَرْضُ غَيْرَ الأَرْضِ وَالسَّمَوَاتُ‏}‏ فَأَيْنَ يَكُونُ النَّاسُ يَوْمَئِذٍ يَا رَسُولَ اللَّهِ فَقَالَ ‏\"‏ عَلَى الصِّرَاطِ ‏\"‏ ‏.‏","A'isha reported:I asked Allah's Messenger (ﷺ) about the words of Allah, the Exalted and Glorious:\" The day when the earth would be changed for another earth and Heaven would be changed for another Heaven (XiV. 48), (and inquired: ) (Allah's Messenger), where would the people be on that day? He said: They would be on the Sirat","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... আয়িশাহ্ (রাযিঃ",""],[7057,7057,"2792","আবদুল মালিক ইবনু শু’আয়ব ইবনুল লায়স (রহঃ) ..... আবু সাঈদ আল খুদরী (রাযিঃ) এর রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে বর্ণিত। তিনি বলেন, সমস্ত ভূখণ্ড কিয়ামতের দিন একটি রুটির মতো হয়ে যাবে। আল্লাহ সেটি নিজ হাতে এপাশ-ওপাশ করবেন, যেমন তোমাদের মাঝে কেউ সফরের সময় নিজ রুটি এপাশ-ওপাশ করে। এ দিয়ে হবে জান্নাতবাসীর জন্য আতিথেয়তা। এমন সময় এক ইয়াহুদী লোক এসে বলল, হে আবুল কাসিম! রহমান আপনার প্রতি বারাকাত দান করুন। কিয়ামতের দিন জান্নাতবাসীদের আতিথেয়তা সম্পর্কে আপনাকে জানাব কি? তিনি বললেন, হ্যাঁ। ইয়াহুদী বলল, এ পৃথিবীটি একটি রুটির রূপ ধারণ করবে, যেমন রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছিলেন। রাবী বলেন, তখন রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাদের দিকে লক্ষ্য করে এমনভাবে হেসে দিলেন যে, তার মাড়ির মুবারক দাঁত প্রকাশিত হয়ে পড়েছিল। ইয়াহুদী বলল, তাদের তরকারি কি হবে তা কি আপনাকে বলব? তিনি বললেন, হ্যাঁ। সে বলল, বালাম এবং নূন। সহাবাগণ প্রশ্ন করলেন, তা কি? সে বলল, ষাড় এবং মাছ- যাদের কলিজার বাড়তি অংশ থেকে সত্তর হাজার লোক আহার করতে পারবে। (ইসলামিক ফাউন্ডেশন ৬৮০০, ইসলামিক সেন্টার)","حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ شُعَيْبِ بْنِ اللَّيْثِ، حَدَّثَنِي أَبِي، عَنْ جَدِّي، حَدَّثَنِي خَالِدُ بْنُ يَزِيدَ، عَنْ سَعِيدِ بْنِ أَبِي هِلاَلٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ تَكُونُ الأَرْضُ يَوْمَ الْقِيَامَةِ خُبْزَةً وَاحِدَةً يَكْفَؤُهَا الْجَبَّارُ بِيَدِهِ كَمَا يَكْفَأُ أَحَدُكُمْ خُبْزَتَهُ فِي السَّفَرِ نُزُلاً لأَهْلِ الْجَنَّةِ ‏\"‏ ‏.‏ قَالَ فَأَتَى رَجُلٌ مِنَ الْيَهُودِ فَقَالَ بَارَكَ الرَّحْمَنُ عَلَيْكَ أَبَا الْقَاسِمِ أَلاَ أُخْبِرُكَ بِنُزُلِ أَهْلِ الْجَنَّةِ يَوْمَ الْقِيَامَةِ قَالَ ‏\"‏ بَلَى ‏\"‏ ‏.‏ قَالَ تَكُونُ الأَرْضُ خُبْزَةً وَاحِدَةً - كَمَا قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم - قَالَ فَنَظَرَ إِلَيْنَا رَسُولُ اللَّهِ صلى الله عليه وسلم ثُمَّ ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ قَالَ أَلاَ أُخْبِرُكَ بِإِدَامِهِمْ قَالَ ‏\"‏ بَلَى ‏\"‏ ‏.‏ قَالَ إِدَامُهُمْ بَالاَمُ وَنُونٌ ‏.‏ قَالُوا وَمَا هَذَا قَالَ ثَوْرٌ وَنُونٌ يَأْكُلُ مِنْ زَائِدَةِ كَبِدِهِمَا سَبْعُونَ أَلْفًا ‏.‏","Abu al-Sa'id Khudri reported Allah's Messenger (ﷺ) as saying that the earth would turn to be one single bread on the Day of Resurrection and the Almighty would turn it in His hand as one of you turns a loaf while on a journey. It would be a feast arranged in the honour of the people of Paradise. He (the narrator) further narrated that a person from among the Jews came and he said:Abu al-Qasim, may the Compassionate Lord be pleased with you! May I inform you about the feast arranged in honour of the people of Paradise on the Day of Resurrection? He said: Do it, of course. He said: The earth would become one single bread. Then Allah's Messenger (ﷺ) looked towards us and laughed until his molar teeth became visible. He then again said: May I inform you about that with which they would season it? He said: Do it, of course. He said: Their seasoning would be balim and fish. The Companions of the Prophet (ﷺ) said: What is this balam? He said: Ox and fish from whose excessive livers seventy thousand people would be able to eat","",""],[7058,7058,"2793","ইয়াহইয়া ইবনু হাবীব আল হারিসী (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ দশজন ইয়াহুদী ব্যক্তি যদি আমার অনুসরণ করতো তাহলে এ ভূখণ্ডে মুসলিম হওয়া ছাড়া কোন ইয়াহুদী আর অবশিষ্ট থাকত না। (ইসলামিক ফাউন্ডেশন ৬৮০১, ইসলামিক সেন্টার)","حَدَّثَنَا يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ، حَدَّثَنَا خَالِدُ بْنُ الْحَارِثِ، حَدَّثَنَا قُرَّةُ، حَدَّثَنَا مُحَمَّدٌ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏ \"‏ لَوْ تَابَعَنِي عَشْرَةٌ مِنَ الْيَهُودِ لَمْ يَبْقَ عَلَى ظَهْرِهَا يَهُودِيٌّ إِلاَّ أَسْلَمَ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:If ten scholars of the Jews would follow me, no Jew would be left upon the surface of the earth who would not embrace Islam","ইয়াহইয়া ইবনু হাবীব আল হারিসী (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ",""],[7059,7059,"2794.01","উমর ইবনু হাফস্ ইবনু গিয়াস (রহঃ) ..... আবদুল্লাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, একদা আমি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সঙ্গে এক ফসলি জমিতে চলছিলাম। সে সময় তিনি একটি খেজুর শাখার ছড়ির উপর ভর দিয়ে যাচ্ছিলেন। হঠাৎ তিনি ইয়াহুদীদের একটি দলের পাশ দিয়ে অতিক্রম করলেন। তখন তারা একজন আরেকজনকে বলাবলি করতে লাগল, রূহ সম্বন্ধে তাকে প্রশ্ন করো। তাদের কেউ বলল, কি সন্দেহ তৈরি হয়েছে তোমাদের যে, তোমরা তাকে প্রশ্ন করবে? তোমাদের যেন এমন কথার সম্মুখীন না হতে হয়, যা তোমরা অপছন্দ করো। এরপরও তারা বলল, তাকে অবশ্যই প্রশ্ন করো। পরিশেষে তাদের কেউ উঠে গিয়ে তাকে রূহ সম্বন্ধে প্রশ্ন করল। রাবী বলেন, তখন নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম চুপ রইলেন। তার কোন উত্তর দিলেন না। আমি বুঝতে পারলাম, তার উপর ওয়াহী অবতীর্ণ হচ্ছে। রাবী বলেন, আমি নিজের স্থানে দাঁড়িয়ে রইলাম। এরপর ওয়াহী অবতীর্ণ শেষ হলে তিনি বললেন, \"তোমাকে তারা রূহ সম্পর্কে জিজ্ঞেস করে; বলো, রূহ আমার প্রতিপালকের একটি আদেশ মাত্র এবং তোমাদের অতি নগণ্য জ্ঞান দেয়া হয়েছে\" (সূরা আল ইসরা ১৭ঃ ৮৫)। (ইসলামিক ফাউন্ডেশন ৬৮০২, ইসলামিক সেন্টার)","حَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنِي إِبْرَاهِيمُ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ بَيْنَمَا أَنَا أَمْشِي، مَعَ النَّبِيِّ صلى الله عليه وسلم فِي حَرْثٍ وَهُوَ مُتَّكِئٌ عَلَى عَسِيبٍ إِذْ مَرَّ بِنَفَرٍ مِنَ الْيَهُودِ فَقَالَ بَعْضُهُمْ لِبَعْضٍ سَلُوهُ عَنِ الرُّوحِ فَقَالُوا مَا رَابَكُمْ إِلَيْهِ لاَ يَسْتَقْبِلُكُمْ بِشَىْءٍ تَكْرَهُونَهُ ‏.‏ فَقَالُوا سَلُوهُ فَقَامَ إِلَيْهِ بَعْضُهُمْ فَسَأَلَهُ عَنِ الرُّوحِ - قَالَ - فَأَسْكَتَ النَّبِيُّ صلى الله عليه وسلم فَلَمْ يَرُدَّ عَلَيْهِ شَيْئًا فَعَلِمْتُ أَنَّهُ يُوحَى إِلَيْهِ - قَالَ - فَقُمْتُ مَكَانِي فَلَمَّا نَزَلَ الْوَحْىُ قَالَ ‏{‏ وَيَسْأَلُونَكَ عَنِ الرُّوحِ قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلاَّ قَلِيلاً‏}‏","Abdullah (b. Mas`ud) reported:As I was going along with Allah's Apostle (ﷺ) in a cultivable land and he (the Holy Prophet) was walking with the support of a wood, a group of Jews happened to meet him. Some of them said to the others: Ask him about the Soul. They said: What is your doubt about it? There is a possibility that you may ask him about anything (the answer of) which you may not like. They said: Ask him. So one amongst them asked him about the Soul. Allah's Messenger (ﷺ) kept quiet and he gave no reply and I came to know that revelation was being sent to him, so I stood at my place and thus this revelation descended upon him:\" They ask thee about the Soul. Say: The Soul is by the Commandment of my Lord, and of Knowledge you are given but a little\" (xvii)","উমর ইবনু হাফস্ ইবনু গিয়াস (রহঃ) ..... আবদুল্লাহ (রাযিঃ",""],[7060,7060,"2794.02","(…) আবু বাকর ইবনু আবূ শাইবাহ ও আবু সাঈদ আল আশাজ্জ, ইসহাক ইবনু ইবরাহীম আল হানযালী এবং আলী ইবনু খাশরাম (রহঃ) ..... আবদুল্লাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সঙ্গে মদীনার একটি ফসলি জমিতে হাঁটছিলাম। তারপর তিনি হাফসের অবিকল হাদীস বর্ণনা করেছেন। তবে ওয়াকী এর হাদীসে আছেوَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلاَّ قَلِيلاًআর খাশরামের সূত্রে বর্ণিত ঈসার হাদীসে রয়েছে وَمَا أُوتُوا (ইসলামিক ফাউন্ডেশন ৬৮০৩, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو سَعِيدٍ الأَشَجُّ قَالاَ حَدَّثَنَا وَكِيعٌ، ح وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ، وَعَلِيُّ بْنُ خَشْرَمٍ، قَالاَ أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، كِلاَهُمَا عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ كُنْتُ أَمْشِي مَعَ النَّبِيِّ صلى الله عليه وسلم فِي حَرْثٍ بِالْمَدِينَةِ ‏.‏ بِنَحْوِ حَدِيثِ حَفْصٍ غَيْرَ أَنَّ فِي حَدِيثِ وَكِيعٍ وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلاَّ قَلِيلاً ‏.‏ وَفِي حَدِيثِ عِيسَى بْنِ يُونُسَ وَمَا أُوتُوا ‏.‏ مِنْ رِوَايَةِ ابْنِ خَشْرَمٍ ‏.‏","Abdullah reported:I was walking along with Allah's Apostle (ﷺ) in a field of Medina. The rest of the hadith is the same, but there is a slight variation of wording","",""],[7061,7061,"2794.03","আবূ সাঈদ আল আশাজ্জ (রহঃ) ..... ‘আবদুল্লাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, একদা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কোন এক খেজুর বাগানে খেজুর ডালের লাঠির উপর ভর করে চলছিলেন। এরপর তিনি আ'মাশ হতে বর্ণিত হাদীসের হুবহু বর্ণনা করেছেন। কিন্তু তার বর্ণনার মধ্যে রয়েছে অর্থাৎ- \"এ বিষয়ে তোমাদেরকে সামান্য জ্ঞানই দান করা হয়েছে\"। (ইসলামিক ফাউন্ডেশন ৬৮০৪, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو سَعِيدٍ الأَشَجُّ، قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ إِدْرِيسَ، يَقُولُ سَمِعْتُ الأَعْمَشَ، يَرْوِيهِ عَنْ عَبْدِ اللَّهِ بْنِ مُرَّةَ، عَنْ مَسْرُوقٍ، عَنْ عَبْدِ اللَّهِ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم فِي نَخْلٍ يَتَوَكَّأُ عَلَى عَسِيبٍ ‏.‏ ثُمَّ ذَكَرَ نَحْوَ حَدِيثِهِمْ عَنِ الأَعْمَشِ وَقَالَ فِي رِوَايَتِهِ وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلاَّ قَلِيلاً ‏.‏","Abdullah reported that Allah's Apostle (ﷺ) was reclining against a tree in the garden. The rest of the hadith is the same with a slight variation of wording","আবূ সাঈদ আল আশাজ্জ (রহঃ) ..... ‘আবদুল্লাহ (রাযিঃ",""],[7062,7062,"2795.01","আবু বাকর ইবনু আবূ শাইবাহ ও আবদুল্লাহ ইবনু সাঈদ আল আশাজ্জ (রহঃ) ..... খাব্বাব (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আস ইবনু ওয়ায়িল এর কাছে আমার কিছু পাওনা ছিল। এর উসূলান্তে আমি তার নিকট গেলাম। সে বলল, যে পর্যন্ত তুমি মুহাম্মাদকে অস্বীকার না করবে ততক্ষণ পর্যন্ত তোমার পাওনা দিব না। এ কথা শুনে আমি তাকে বললাম, আমি কক্ষনো মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে অস্বীকার করব না, তুমি মরার পর আবার জীবিত হয়ে আসলেও। সে বলল, আমি কি মৃত্যুর পর আবার জীবিত হয়ে উঠব? তাহলে তখনই আমি আমার সম্পদ এবং সন্তানাদি লাভ করে তোমার পাওনা পরিশোধ করব। তখন এ আয়াতটি অবতীর্ণ হয়, \"আপনি কি দেখেছেন তাকে যে আমার আয়াতসমূহ উপেক্ষা করে এবং বলে, আমাকে তো ধন-সম্পদ ও সন্তানাদি দেয়া হবে।\" \"..... আর সে আমার কাছে একাকী আসবে\"— তখন এ আয়াতটি নাযিল হয়। (ইসলামিক ফাউন্ডেশন ৬৮০৫, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَعَبْدُ اللَّهِ بْنُ سَعِيدٍ الأَشَجُّ، - وَاللَّفْظُ لِعَبْدِ اللَّهِ - قَالاَ حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كَانَ لِي عَلَى الْعَاصِ بْنِ وَائِلٍ دَيْنٌ فَأَتَيْتُهُ أَتَقَاضَاهُ فَقَالَ لِي لَنْ أَقْضِيَكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ - قَالَ - فَقُلْتُ لَهُ إِنِّي لَنْ أَكْفُرَ بِمُحَمَّدٍ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ ‏.‏ قَالَ وَإِنِّي لَمَبْعُوثٌ مِنْ بَعْدِ الْمَوْتِ فَسَوْفَ أَقْضِيكَ إِذَا رَجَعْتُ إِلَى مَالٍ وَوَلَدٍ ‏.‏ قَالَ وَكِيعٌ كَذَا قَالَ الأَعْمَشُ قَالَ فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏ أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا‏}‏ إِلَى قَوْلِهِ ‏{‏ وَيَأْتِينَا فَرْدًا‏}‏","Khabbab reported that Al-`As b. Wa'il owed debt to me. I came to him in order to demand that. He said:I will never repay you unless you belie Muhammad. I said: I would never belie Muhammad until you die and you are again raised up. He said: When I would be raised up after death, I would repay your debt when I would get my property and children back. Waki` said: This is how Al-A`mash has narrated and it was on this occasion that this verse was revealed: \"Hast thou seen him who disbelieves in Our message and says: I shall certainly be given wealth and children\" (xix, 77) up to \"he would come to Us alone\" (xix)","আবু বাকর ইবনু আবূ শাইবাহ ও আবদুল্লাহ ইবনু সাঈদ আল আশাজ্জ (রহঃ) ..... খাব্বাব (রাযিঃ",""],[7063,7063,"2795.02","(…) আবূ কুরায়ব, ইবনু নুমায়র, ইসহাক ইবনু ইবরাহীম ও ইবনু আবূ উমার, ..... আমাশ (রহঃ) এর সানাদে এ সূত্রে ওয়াকী’র হাদীসের অবিকল বর্ণনা করেছেন। তবে জারীর এর হাদীসের মধ্যে অতিরিক্ত আছে যে, খাব্বাব (রাযিঃ) বলেন, জাহিলী যুগে আমি কর্মকার ছিলাম। তখন আস ইবনু ওয়ায়িলকে আমি একটি কাজ করে দিয়েছিলাম। এরপর আমি তা আদায় করার জন্য তার কাছে গেলাম। (ইসলামিক ফাউন্ডেশন ৬৮০৬, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، ح وَحَدَّثَنَا ابْنُ نُمَيْرٍ، حَدَّثَنَا أَبِي ح، وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا جَرِيرٌ، ح وَحَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، كُلُّهُمْ عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ ‏.‏ نَحْوَ حَدِيثِ وَكِيعٍ وَفِي حَدِيثِ جَرِيرٍ قَالَ كُنْتُ قَيْنًا فِي الْجَاهِلِيَّةِ فَعَمِلْتُ لِلْعَاصِ بْنِ وَائِلٍ عَمَلاً فَأَتَيْتُهُ أَتَقَاضَاهُ ‏.‏","This hadith has been narrated on the authority of Khabbib through another chain of transmitters and the words are. I in the pre-Islamic days used to work as an iron-smith. I did some work for 'As b. Wa'il and came to him for getting the remuneration of my wages","",""],[7064,7064,"2796","উবাইদুল্লাহ ইবনু মুআয আল আম্বারী (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, একদা আবু জাহল বলল, \"হে আল্লাহ! এটা যদি তোমার তরফ থেকে সত্য হয়, তাহলে আমাদের উপর আকাশ থেকে প্রস্তর বর্ষণ করো অথবা আমাদের কঠিন ‘আযাব দাও।\" তখন অবতীর্ণ হলোঃ \"আল্লাহ এমন নন যে, আপনি তাদের মাঝে অবস্থান করবেন আর তিনি তাদের আযাব দিবেন এবং আল্লাহ এমনও নন যে, তারা মার্জনা প্রার্থনা করবে আর তিনি তাদের আযাব দিবেন। আর তাদের কি বা বলার আছে যে, আল্লাহ তাদের আযাব দিবেন না, যদিও তারা লোকেদের মসজিদুল হারাম হতে নিবৃত্ত করে?\" (সূরা আল আনফাল ৮ঃ ৩৩-৩৪) ..... আয়াতের শেষ পর্যন্ত। (ইসলামিক ফাউন্ডেশন ৬৮০৭, ইসলামিক সেন্টার)","حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْحَمِيدِ الزِّيَادِيِّ، أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ قَالَ أَبُو جَهْلٍ اللَّهُمَّ إِنْ كَانَ هَذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ ‏.‏ فَنَزَلَتْ ‏{‏ وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ * وَمَا لَهُمْ أَلاَّ يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ‏}‏ إِلَى آخِرِ الآيَةِ ‏.‏","Anas b. Malik reported that Abu Jahl said:O Allah, if he is true, then shower upon us the volley of stones from the sky or inflict upon us a grievous torment, and it was on this occasion that this verse was revealed:\" 'Allah would never torment them so long as you are amongst them. And Allah is not going to torment them as long as they seek forgiveness. And why is it that Allah should not torment them and they prevent people from coming to the sacred mosque....\" (viii. 34) to the end","উবাইদুল্লাহ ইবনু মুআয আল আম্বারী (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ",""],[7065,7065,"2797","উবাইদুল্লাহ ইবনু মুআয (রহঃ) এবং মুহাম্মাদ ইবনু আবদুল আ’লা আল কায়সী (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আবু জাহল বলেছিল, মুহাম্মদ কি তোমাদের মাঝে তার মুখমণ্ডল জমিনের উপর রাখে? লোকেরা বলল, হ্যাঁ রাখে। তখন সে বলল, আমি লাত এবং উয্যার শপথ করে বলছি, আমি যদি তাকে এমন করতে দেখি তবে নিশ্চয়ই আমি তার ঘাড় পদদলিত করব, অথবা তার মুখমণ্ডল আমি মাটিতে মেখে দিব। (নাউযুবিল্লাহ) তারপর একদা রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সালাত আদায়ে রত ছিলেন। এমন সময় আবূ জাহল রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর গর্দানকে পদদলিত করার উদ্দেশে তার কাছে আসলো। একটু অগ্রসর হয়ে অকস্মাৎ সে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে মুখ ফিরিয়ে দ্রুত পিছনে সরে আসল এবং দু' হাত দিয়ে নিজেকে বাঁচাতে লাগল। এ দেখে তাকে প্রশ্ন করা হলো, তোমার কি হয়েছে? উত্তরে সে বলল, আমি দেখেছি যে, আমার এবং তার মধ্যে আগুনের একটি প্রকাণ্ড খাদক, ভয়াবহ অবস্থা এবং কতগুলো ডানা। অতঃপর রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেন, সে যদি আমার নিকটে আসত, তবে ফেরেশতাগণ তার অঙ্গ-প্রত্যঙ্গকে ছিন্নবিচ্ছিন্ন করে ফেলতো। রাবী বলেন, অতঃপর আল্লাহ তা’আলা অবতীর্ণ করলেন। রাবী (আবু হাযিম) বলেন, আবু হুরাইরাহ (রাযিঃ) এর হাদীসের মধ্যে এ অবতীর্ণ আয়াতটি আছে, না এ মর্মে তার কাছে কোন খবর পৌছেছে, তা আমাদের জানা নেই। “কক্ষনো ঠিক নয়, মানুষ তো সীমালঙ্ঘন করেই থাকে, কেননা সে নিজেকে স্বয়ংসম্পূর্ণ মনে করছে। আপনার প্রতিপালকের কাছে ফিরে যেতে হবে এটা সুনিশ্চিত। আপনি বলুন তো সে ব্যক্তি সম্পর্কে যে বাধা দেয় এক বান্দাকে যখন সে সালাত আদায় করে। আপনি বলুন তো যদিও সে সালাত আদায়কারী ব্যক্তিটি সৎপথে থাকে এবং তাকওয়ার আদেশ করে এমন ব্যক্তিকে কি বাধা দেয়া ব্যক্তি তবে সে কি জানে না যে, আল্লাহ প্রত্যক্ষ করেন? সাবধান, সে যদি বিরত না হয়, তবে আমি অবশ্যই তাকে হেঁচড়িয়ে নিয়ে যাব মস্তকের অগ্রভাগের কেশগুচ্ছ ধরে, সেটি মিথ্যাচারী পাপিষ্ঠের কেশগুচ্ছ। অতএব সে তার নাসিয়াহ অর্থাৎ- তার সম্প্রদায়কে আহবান করুক। আমি যবনিয়াকে (সম্প্রদায়কে) আহবান করব। কক্ষনো তুমি তার অনুকরণ করো না”— (সূরা আল ‘আলাক ৯৬ঃ ৬-১৯)। উবাইদুল্লাহ তার হাদীসে এতটুকু বাড়িয়েছেনঃ রাবী আবু হুরাইরাহ (রাযিঃ) বলেন, তার (রসূল) আদেশ আল্লাহর নির্দেশ অনুযায়ী (প্রযোজ্য)। ইবনু আবদুল আ’লা বৃদ্ধি করেছেন فَلْيَدْعُ نَادِيَهُ অর্থাৎقَوْمَهُ ও তার সম্প্রদায়কে ডাকুক। (ইসলামিক ফাউন্ডেশন ৬৮০৮, ইসলামিক সেন্টার)","حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، وَمُحَمَّدُ بْنُ عَبْدِ الأَعْلَى الْقَيْسِيُّ، قَالاَ حَدَّثَنَا الْمُعْتَمِرُ، عَنْ أَبِيهِ، حَدَّثَنِي نُعَيْمُ بْنُ أَبِي هِنْدٍ، عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ أَبُو جَهْلٍ هَلْ يُعَفِّرُ مُحَمَّدٌ وَجْهَهُ بَيْنَ أَظْهُرِكُمْ قَالَ فَقِيلَ نَعَمْ ‏.‏ فَقَالَ وَاللاَّتِ وَالْعُزَّى لَئِنْ رَأَيْتُهُ يَفْعَلُ ذَلِكَ لأَطَأَنَّ عَلَى رَقَبَتِهِ أَوْ لأُعَفِّرَنَّ وَجْهَهُ فِي التُّرَابِ - قَالَ - فَأَتَى رَسُولَ اللَّهِ صلى الله عليه وسلم وَهُوَ يُصَلِّي زَعَمَ لِيَطَأَ عَلَى رَقَبَتِهِ - قَالَ - فَمَا فَجِئَهُمْ مِنْهُ إِلاَّ وَهُوَ يَنْكِصُ عَلَى عَقِبَيْهِ وَيَتَّقِي بِيَدَيْهِ - قَالَ - فَقِيلَ لَهُ مَا لَكَ فَقَالَ إِنَّ بَيْنِي وَبَيْنَهُ لَخَنْدَقًا مِنْ نَارٍ وَهَوْلاً وَأَجْنِحَةً ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لَوْ دَنَا مِنِّي لاَخْتَطَفَتْهُ الْمَلاَئِكَةُ عُضْوًا عُضْوًا ‏\"‏ ‏.‏ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ لاَ نَدْرِي فِي حَدِيثِ أَبِي هُرَيْرَةَ أَوْ شَىْءٌ بَلَغَهُ ‏{‏ كَلاَّ إِنَّ الإِنْسَانَ لَيَطْغَى * أَنْ رَآهُ اسْتَغْنَى * إِنَّ إِلَى رَبِّكَ الرُّجْعَى * أَرَأَيْتَ الَّذِي يَنْهَى * عَبْدًا إِذَا صَلَّى * أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى * أَوْ أَمَرَ بِالتَّقْوَى * أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى‏}‏ - يَعْنِي أَبَا جَهْلٍ - ‏{‏ أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَى * كَلاَّ لَئِنْ لَمْ يَنْتَهِ لَنَسْفَعًا بِالنَّاصِيَةِ * نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ * فَلْيَدْعُ نَادِيَهُ * سَنَدْعُ الزَّبَانِيَةَ * كَلاَّ لاَ تُطِعْهُ‏}‏ زَادَ عُبَيْدُ اللَّهِ فِي حَدِيثِهِ قَالَ وَأَمَرَهُ بِمَا أَمَرَهُ بِهِ ‏.‏ وَزَادَ ابْنُ عَبْدِ الأَعْلَى فَلْيَدْعُ نَادِيَهُ يَعْنِي قَوْمَهُ ‏.‏","Abu Huraira reported that Abu Jahl asked (people) whether Muhammad placed his face (on the ground) in their presence. It was said to him:Yes. He said: By Lat and `Uzza. If I were to see him do that, I would trample his neck, or I would smear his face with dust. He came to Allah's Messenger (ﷺ) as he was engaged in prayer and thought of trampling his neck (and the people say) that he came near him but turned upon his heels and tried to repulse something with his hands. It was said to him: What is the matter with you? He said: There is between me and him a ditch of fire and terror and wings. Thereupon Allah's Messenger (may peace he upon him) said: If he were to come near me the angels would have torn him to pieces. Then Allah, the Exalted and Glorious, revealed this verse- (the narrator) said: We do not know whether it is the hadith transmitted by Abu Huraira or something conveyed to him from another source: \"Nay, man is surely inordinate, because he looks upon himself as self-sufficient. Surely to thy Lord is the return. Hast thou seen him who forbids a servant when he prays? Seest thou if he is on the right way, or enjoins observance of piety? Seest thou if he [Abu Jahl] denies and turns away? Knowest he not that Allah sees? Nay, if he desists not, We will seize him by the forelock-a lying, sinful forelock. Then let him summon his council. We will summon the guards of the Hell. Nay! Obey not thou him\" (lcvi, 6-19). (Rather prostrate thyself.) Ubaidullah made this addition: It was after this that (prostration) was enjoined upon and Ibn Abd al-Ala made this addition that by \"Nadiyah\" he meant his people","",""],[7066,7066,"2798.01","ইসহাক ইবনু ইবরাহীম (রহঃ) ..... মাসরুক (রহঃ) থেকে বর্ণিত। তিনি বলেন, আমরা ‘আবদুল্লাহ ইবনু মাসউদ (রাযিঃ) এর কাছে উপবিষ্ট ছিলাম। এ সময় তিনি আমাদের মাঝে এক পার্শ্বদেশ হয়ে ঘুমিয়েছিলেন। এমতাবস্থায় তার কাছে জনৈক লোক এসে বলল, হে আবু আবদুর রহমান। কিনদা দ্বারপ্রান্তে এক বক্তা বলছেন, কুরআনে বর্ণিত ধোয়ার কাহিনীটি ভবিষ্যতে সংঘটিত হবে। তা প্রবাহিত হয়ে কাফিরদের শ্বাসরুদ্ধ করে দিবে এবং এতে মুমিনদের সর্দির মতো অবস্থা হবে। এ কথা শুনে তিনি গোস্বা হয়ে বসলেন এবং বললেন, হে লোক সকল! তোমরা আল্লাহকে ভয় কর। তোমাদের কেউ কোন কথার জ্ঞান থাকলে সে যেন তা-ই বলে। আর যে না জানে সে যেন বলে- আল্লাহই সবচেয়ে ভাল জানে। কেননা প্রকৃত জ্ঞানের কথা হচ্ছে এই যে, যে বিষয়ে তার জ্ঞান নেই সে বিষয়ে বলবে, আল্লাহই অধিক ভাল জানেন। কারণ আল্লাহ তা’আলা তার নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে বলেছেন, \"বলো, আমি এর জন্য তোমাদের কাছে কোন প্রতিফল চাই না এবং আমি মিথ্যা দাবীদারদের অন্তর্ভুক্ত নই।\" প্রকৃত অবস্থা তো এই যে, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম যখন লোকেদের মাঝে দীন বিমুখ দেখলেন, তখন তিনি বলেছিলেন, হে আল্লাহ ইউসুফ (আঃ) এর সময়ের ন্যায় অভাব-অনটনের সাতটি বছর তাদের উপর আপতিত কর। তারপর তাদের উপর অভাব-অনটন এমনভাবে পতিত হলো যে, তা সব কিছুকে নিঃশেষ করে দিল। ফলে ক্ষুধার জ্বালায় তারা চামড়া ও মৃত দেহ খাদ্য উপকরণ হিসেবে গ্রহণ করলো। এমনকি তাদের কোন লোক আকাশের দিকে তাকালে শুধু ধোয়ার মতই দেখতে পেত। অতঃপর আবু সুফইয়ান রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর কাছে এসে বলল, হে মুহাম্মাদ! আপনি তো আল্লাহর আনুগত্যের আদেশ করেন এবং আত্মীয়তার হক আদায় করার আদেশ দিয়ে আসছেন, অথচ আপনার সম্প্রদায় তো ধ্বংস হয়ে গেলো। আপনি তাদের জন্য আল্লাহর কাছে দুআ করুন। (এ প্রসঙ্গে) আল্লাহ তা’আলা বললেনঃ “অতএব আপনি অপেক্ষা করুন সে দিনের, যেদিন স্পষ্ট ধূম্রাচ্ছন্ন হবে আকাশ এবং সেটা আবৃত করে ফেলবে মানব জাতিকে। এ হবে কঠিন শাস্তি। ... তোমরা তো তোমাদের পূর্বাবস্থায় ফিরে যাবে।\" এ পর্যন্ত তিলাওয়াত করলেন। (সূরাহ্ আদ দুখান ৪৪ঃ ১০-১২) ‘আবদুল্লাহ (রাযিঃ) বলেন, আখিরাতের শাস্তি কি লাঘব করা হবে? (আল্লাহ তা’আলা আরো বলেছেন), \"যেদিন আমি তোমাদের সুদৃঢ়ভাবে পাকড়াও করব, অবশ্যই সেদিন আমি তোমাদের নিকট থেকে প্রতিশোধ নিব।\" (সূরাহ্ আদ দুখান ৪৪ঃ ১৬) অনুরূপ এ আয়াতে বাতশাহ্ দ্বারা বদরের যুদ্ধ উদ্দেশ্য করা হয়েছে। কাজেই দুখান (ধোয়ার নিদর্শন), আল বাতশাহ্ (পাকড়াও), লিযাম (আবশ্যিক শাস্তি) এবং রূম (রোমকদের পরাজয়ের কাহিনী) এসব অতীত হয়ে গেছে। (ইসলামিক ফাউন্ডেশন ৬৮০৯, ইসলামিক সেন্টার)","أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ جُلُوسًا وَهُوَ مُضْطَجِعٌ بَيْنَنَا فَأَتَاهُ رَجُلٌ فَقَالَ يَا أَبَا عَبْدِ الرَّحْمَنِ إِنَّ قَاصًّا عِنْدَ أَبْوَابِ كِنْدَةَ يَقُصُّ وَيَزْعُمُ أَنَّ آيَةَ الدُّخَانِ تَجِيءُ فَتَأْخُذُ بِأَنْفَاسِ الْكُفَّارِ وَيَأْخُذُ الْمُؤْمِنِينَ مِنْهُ كَهَيْئَةِ الزُّكَامِ فَقَالَ عَبْدُ اللَّهِ وَجَلَسَ وَهُوَ غَضْبَانُ يَا أَيُّهَا النَّاسُ اتَّقُوا اللَّهَ مَنْ عَلِمَ مِنْكُمْ شَيْئًا فَلْيَقُلْ بِمَا يَعْلَمُ وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ فَإِنَّهُ أَعْلَمُ لأَحَدِكُمْ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏ قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا فَقَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏ ‏.‏ قَالَ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ مِنَ الْجُوعِ وَيَنْظُرُ إِلَى السَّمَاءِ أَحَدُهُمْ فَيَرَى كَهَيْئَةِ الدُّخَانِ فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ جِئْتَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ لَهُمْ - قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ إِلَى قَوْلِهِ ‏{‏ إِنَّكُمْ عَائِدُونَ‏}‏ ‏.‏ قَالَ أَفَيُكْشَفُ عَذَابُ الآخِرَةِ ‏{‏ يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ وَقَدْ مَضَتْ آيَةُ الدُّخَانِ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ ‏.‏","Masruq reported:We were sitting in the company of Abdullah and he was lying on the bed that a person came and said: Abd Abd al-Rabmin, a story-teller at the gates of Kinda says that the verse (of the Qur'an) which deals with the\" smoke\" implies that which is about to come and it would hold the breath of the infidels and would inflict the believers with cold. Thereupon Abdullah got up and said in anger. O people, fear Allah and say only that which one knows amongst you and do not say which he does not know and he should simply say: Allah has the best knowledge for He has the best knowledge amongst all of you. It does not behove him to say that which he does not know. Allah has the best knowledge of it. Verily Allah, the Exalted and Glorious, said to His Prophet (ﷺ) to state:\" I do not ask from you any remuneration and I am not the one to put you in trouble,\" and when Allah's Mesqenger (ﷺ) saw people turning back (from religion) he said: O Allah, afflict thern with seven famines as was done in the case of Yusuf, so they were afflicted with famine by which they were forced to eat everything until they were obliged to eat the hides and the dead bodies because of hunger, and every one of them looked towards the sky and he found a smoke. And Abu Sufyan came and he said: Muhammad, you have come to command us to obey Allah and cement the ties of blood- relation whereas your people are undone; supplicate Allah for tlicm. Thereupon Allah, the Exalted and Glorious, said:\" Wait for the day when there would be clear smoke from the sky which would envelop people and that would be grievous torivent\" up to the words:\" you are going to return to (evil).\" (if this verse implied the torment of the next life) could the chastisement of the next (life) be averted (as the Qur'an states): On the day when We seize (them) with the most violent seizing; surely We shall exact retribution\" (xliv. 16)? The seizing (in the hadith) implies that of the Day of Badr. And so far as the sign of smoke, seizing, inevitability and signs of Rome are concern- ed, they have become things of the past now","ইসহাক ইবনু ইবরাহীম (রহঃ) ..... মাসরুক (রহঃ",""],[7067,7067,"2798.02","আবূ বাকর ইবনু আবূ শাইবাহ, আবূ সাঈদ আল আশাজ্জ, উসমান ইবনু আবু শাইবাহ, ইয়াহইয়া ইবনু ইয়াহইয়া ও আবূ কুরায়ব (রহঃ) ..... মাসরুক (রহঃ) থেকে বর্ণিত। তিনি বলেন, আবদুল্লাহ (রাযিঃ) এর কাছে এক লোক এসে বলল, আমি মসজিদে এক লোককে দেখে এসেছি, সে কুরআনের ইচ্ছামাফিক তাফসীর করছে। সে يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ এ আয়াতের ব্যাখ্যায় বলছে যে, কিয়ামতের দিন ধোয়া এসে লোকেদের আবৃত করে ফেলবে ও তাদের শ্বাসরুদ্ধ করে ফেলবে, এমনকি এতে লোকেদের সর্দির ন্যায় অবস্থা হয়ে যাবে। এ কথা শুনে আবদুল্লাহ (রাযিঃ) বললেন, যে ব্যক্তি যে বিষয়ে জানে সে তা বর্ণনা করবে। আর যে না জানে তার বলা উচিত, আল্লাহই অধিক জ্ঞাত। কেননা অজানা বিষয় সম্বন্ধে আল্লাহই অধিক জ্ঞাত, এ কথা বলাই মানুষের পরিপূর্ণ জ্ঞানের লক্ষণ। কারণ এ বিষয়টি তখনই সংঘটিত হয়েছিল, যখন কুরায়শরা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর অবাধ্যতা করেছিল। তখন তিনি তাদের বিরুদ্ধে দুআ করেন যেন ইউসুফ (আঃ) এর সময়ের সাত বছরের মতো অভাব-অনটন তাদের উপর নিপতিত হয়। এরপর তাদের উপর অভাব-অনটন এবং ক্ষুধার কষ্ট এমনভাবে নিপতিত হলো যে, কেউ আকাশের দিকে তাকালে সে ধূম্ৰাচ্ছন্ন দেখত, এমনকি তারা হাড্ডি খাওয়া শুরু করল। তখন জনৈক লোক এসে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলল, হে আল্লাহর রসূল! মুযার গোত্রের জন্য আল্লাহর কাছে মার্জনা প্রার্থনা করুন। তারা নিশ্চয় ধ্বংস হয়ে গেল। তিনি বললেন, মুযার গোত্রের জন্য তুমি তো দুর্দান্ত সাহসী। রাবী বলেন, তারপর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের জন্য আল্লাহর কাছে দুআ করলেন। তখন আল্লাহ তা’আলা অবতীর্ণ করলেন, “আমি তোমাদের শাস্তি কিছু সময়ের জন্য বিরত রেখেছি। তোমরা তো তোমাদের আগের অবস্থায়ই প্রত্যাবর্তন করবে\"- (সূরাহ্ আদ দুখান ৪৪ঃ ১৫)। রাবী বলেন, অতঃপর তাদের উপর অনবরত বৃষ্টি হলো। এরপর তাদের যখন স্বচ্ছলতা ফিরে এলো তখন তারা আবার আগের অবস্থায় প্রত্যাবর্তন করল। তখন আল্লাহ তা’আলা অবতীর্ণ করলেন, \"অতএব আপনি অপেক্ষা করুন সেদিনের, যেদিন ধূম্রাচ্ছন্ন হবে আকাশ এবং সেটা মানব জাতিকে ঢেকে ফেলবে। এ হবে কঠিন শাস্তি\"- (সুরাহ্ আদ দুখান ৪৪ঃ ১০-১১)। যেদিন আমি তোমাদের শক্তভাবে পাকড়াও করব, সেদিন আমি তোমাদেরকে আযাব দিবই\"- (সূরাহ্ আদ দুখান ৪৪ঃ ১৬)। রাবী বলেন, অর্থাৎ- বদরের দিন। (ইসলামিক ফাউন্ডেশন ৬৮১০, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، وَوَكِيعٌ، ح وَحَدَّثَنِي أَبُو سَعِيدٍ، الأَشَجُّ أَخْبَرَنَا وَكِيعٌ، ح وَحَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، كُلُّهُمْ عَنِ الأَعْمَشِ، ح وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، وَأَبُو كُرَيْبٍ - وَاللَّفْظُ لِيَحْيَى - قَالاَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمِ بْنِ صُبَيْحٍ، عَنْ مَسْرُوقٍ، قَالَ جَاءَ إِلَى عَبْدِ اللَّهِ رَجُلٌ فَقَالَ تَرَكْتُ فِي الْمَسْجِدِ رَجُلاً يُفَسِّرُ الْقُرْآنَ بِرَأْيِهِ يُفَسِّرُ هَذِهِ الآيَةَ ‏{‏ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ قَالَ يَأْتِي النَّاسَ يَوْمَ الْقِيَامَةِ دُخَانٌ فَيَأْخُذُ بِأَنْفَاسِهِمْ حَتَّى يَأْخُذَهُمْ مِنْهُ كَهَيْئَةِ الزُّكَامِ ‏.‏ فَقَالَ عَبْدُ اللَّهِ مَنْ عَلِمَ عِلْمًا فَلْيَقُلْ بِهِ وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ فَإِنَّ مِنْ فِقْهِ الرَّجُلِ أَنْ يَقُولَ لِمَا لاَ عِلْمَ لَهُ بِهِ اللَّهُ أَعْلَمُ ‏.‏ إِنَّمَا كَانَ هَذَا أَنَّ قُرَيْشًا لَمَّا اسْتَعْصَتْ عَلَى النَّبِيِّ صلى الله عليه وسلم دَعَا عَلَيْهِمْ بِسِنِينَ كَسِنِي يُوسُفَ فَأَصَابَهُمْ قَحْطٌ وَجَهْدٌ حَتَّى جَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى بَيْنَهُ وَبَيْنَهَا كَهَيْئَةِ الدُّخَانِ مِنَ الْجَهْدِ وَحَتَّى أَكَلُوا الْعِظَامَ فَأَتَى النَّبِيَّ صلى الله عليه وسلم رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ اسْتَغْفِرِ اللَّهَ لِمُضَرَ فَإِنَّهُمْ قَدْ هَلَكُوا فَقَالَ ‏\"‏ لِمُضَرَ إِنَّكَ لَجَرِيءٌ ‏\"‏ ‏.‏ قَالَ فَدَعَا اللَّهَ لَهُمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ فَمُطِرُوا فَلَمَّا أَصَابَتْهُمُ الرَّفَاهِيَةُ - قَالَ - عَادُوا إِلَى مَا كَانُوا عَلَيْهِ - قَالَ - فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ ‏{‏ يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ قَالَ يَعْنِي يَوْمَ بَدْرٍ ‏.‏","Masruq reported that there came to Abdullah a person and said:I have left behind in the mosque a man who explains the Qur'an according to his personal discretion and he explained this verse:\" So wait for the day when the Heaven brings a clear smoke.\" He says that a smoke would come to the people on the Day of Resurrection anl it will withhold breath and they would be inflicted with cold. 'Abdullah said: He who has knowledge should say something and he who has no knowledge should simply say: Allah is best aware. This reflects the understanding of a person that he should say about that which he does not know that it is Allah who knows best. The fact is that when the Quraish disobeyed Allah's Apostle (ﷺ) he supplicated Allah that they should be afflicted with famine and starvation as was done in case of Yusuf. And they were so much hard pressed that a person would ace the sky and he would see between him and the sky something like smoke and they were so much hard pressed that they began to cat the bones, and a person came to Allah's Apostle (ﷺ) and said: Allah's Messenger. seek forgiveness for the tribe of Mudar for (its people) have been undone. The Messenger (ﷺ) said: For Mudar? You are overbold, but he supplicated Allah for them. It was upon this that this verse was revealed:\" We shall remove the chastisement a little, but they will surely return to evil\" (xliv. 15). lie (the narrator) said: There was a downpoor of rain upon them. When there was some relief for them they returned to the same position as they had been before, and Allah, the Exalted and Glorious, revealed this verse:\" So wait for the day when the heaven brings a clear smoke enveloping people. This is a grievous torment on the day when We seize them with the most violent seizing; surely, We shall exact retribution.\" And this (seizing) implied (Battle) of Badr","",""],[7068,7068,"2798.03","(…) কুতাইবাহ ইবনু সাঈদ (রহঃ) ..... আবদুল্লাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, পাঁচটি বিষয় অতীত হয়ে গেছেঃ ধোঁয়া, শাস্তি, রোম এর পরাজয়, পাকড়াও এবং চন্দ্রের নিদর্শন অর্থাৎ বিদীর্ণ হওয়া। (ইসলামিক ফাউন্ডেশন ৬৮১১, ইসলামিক সেন্টার)","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ عَبْدِ اللَّهِ، قَالَ خَمْسٌ قَدْ مَضَيْنَ الدُّخَانُ وَاللِّزَامُ وَالرُّومُ وَالْبَطْشَةُ وَالْقَمَرُ ‏.‏","Abdullah said that five signs have (become things) of the past (and have proved the truth of the Holy Prophet):(Enveloping) by the smoke, inevitable (punishment to the Meccans at Badr), (the victory of) Rome, (violent) seizing (of the Meccans at Badr) and (the splitting up of) the Moon","…) কুতাইবাহ ইবনু সাঈদ (রহঃ) ..... আবদুল্লাহ (রাযিঃ",""],[7069,7069,"2798.04","(…/...) আবু সাঈদ আল আশাজ্জ, ওয়াকী (রহঃ) এর সূত্রে আ'মাশ (রহঃ) হতে এ সানাদে অবিকল হাদীস বর্ণনা করেন। (ইসলামিক ফাউন্ডেশন ৬৮১১, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو سَعِيدٍ الأَشَجُّ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏","This hadith has been narrated on the authority of A'mash with the same chain of transmitters","",""],[7070,7070,"2799","মুহাম্মাদ ইবনুল মুসান্না, মুহাম্মাদ ইবনু বাশশার ও আবু বকর ইবনু আবূ শাইবাহ (রহঃ) ... উবাই ইবনু কা'ব (রাযিঃ) আল্লাহর বাণী- “বড় বড় শাস্তির পূর্বে তাদের আমি অবশ্যই ছোট ছোট শাস্তি আস্বাদন করাব”— (সুরা আস্ সিজদা ৩২ঃ ২১) এ আয়াতের ব্যাখ্যায় বলেছেনঃ উদ্দেশ্য হলো পার্থিব বিপদাপদ, রোমের পরাজয়, পাকড়াও অথবা ধোঁয়া। পাকড়াও না ধোঁয়া’ এ সম্পর্কে শুবাহ সন্দেহ প্রকাশ করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮১৩, ইসলামিক সেন্টার)","حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَمُحَمَّدُ بْنُ بَشَّارٍ، قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، ح وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، - وَاللَّفْظُ لَهُ - حَدَّثَنَا غُنْدَرٌ، عَنْ شُعْبَةَ، عَنْ قَتَادَةَ، عَنْ عَزْرَةَ، عَنِ الْحَسَنِ الْعُرَنِيِّ، عَنْ يَحْيَى بْنِ الْجَزَّارِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ أُبَىِّ، بْنِ كَعْبٍ فِي قَوْلِهِ عَزَّ وَجَلَّ ‏{‏ وَلَنُذِيقَنَّهُمْ مِنَ الْعَذَابِ الأَدْنَى دُونَ الْعَذَابِ الأَكْبَرِ‏}‏ قَالَ مَصَائِبُ الدُّنْيَا وَالرُّومُ وَالْبَطْشَةُ أَوِ الدُّخَانُ ‏.‏ شُعْبَةُ الشَّاكُّ فِي الْبَطْشَةِ أَوِ الدُّخَانِ ‏.‏","Ubayy b. Ka'b reported that the words of Allah, the Exalted and Glorious:\" We will, surely, make them taste the lesser punishment before the severer punishment (that haply they may return)\" (xxxii. 21) imply the torments of the world. (victory of) Rome, seizing (of the Meccans), or smoke. And Shalba was in doubt about seizing or smoke","",""],[7071,7071,"2800.01","আমর আন নাকিদ ও যুহায়র ইবনু হারব (রহঃ) ..... আবদুল্লাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সময় চন্দ্ৰ দু’টুকরো হয়েছিল। তখন রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছিলেনঃ তোমরা সাক্ষী থাকো। (ইসলামিক ফাউন্ডেশন ৬৮১৪, ইসলামিক সেন্টার)","حَدَّثَنَا عَمْرٌو النَّاقِدُ، وَزُهَيْرُ بْنُ حَرْبٍ، قَالاَ حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنِ ابْنِ أَبِي، نَجِيحٍ عَنْ مُجَاهِدٍ، عَنْ أَبِي مَعْمَرٍ، عَنْ عَبْدِ اللَّهِ، قَالَ انْشَقَّ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم بِشِقَّتَيْنِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ اشْهَدُوا ‏\"‏ ‏.‏","Abu Ma'mar reported on the authority of Abdullah that the moon was split up during lifetime by Allah's Messenger (ﷺ) in two parts and Allah's Messenger (ﷺ) said:Bear testimony to this","আমর আন নাকিদ ও যুহায়র ইবনু হারব (রহঃ) ..... আবদুল্লাহ (রাযিঃ",""],[7072,7072,"2800.02","আবু বাকর ইবনু আবু শাইবাহ, আবু কুরায়ব, ইসহাক ইবনু ইবরাহীম, ‘উমার ইবনু হাফস ইবনু গিয়াস ও মিন্‌জাব ইবনুল হারিস আত তামীমী (রহঃ) ..... আবদুল্লাহ ইবনু মাসউদ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, মিনায় আমরা রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সাথে ছিলাম। এমতাবস্থায় অকস্মাৎ চাঁদ দু'টুকরো হয়ে গেল। এক টুকরো পাহাড়ের পিছনে পতিত হল এবং অপর টুকরো পাহাড়ের সামনে। তখন রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাদেরকে বললেন, তোমরা সাক্ষী থাকো। (ইসলামিক ফাউন্ডেশন ৬৮১৫, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ جَمِيعًا عَنْ أَبِي، مُعَاوِيَةَ ح وَحَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي كِلاَهُمَا، عَنِ الأَعْمَشِ، ح وَحَدَّثَنَا مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ، - وَاللَّفْظُ لَهُ - أَخْبَرَنَا ابْنُ مُسْهِرٍ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ أَبِي مَعْمَرٍ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم بِمِنًى إِذَا انْفَلَقَ الْقَمَرُ فِلْقَتَيْنِ فَكَانَتْ فِلْقَةٌ وَرَاءَ الْجَبَلِ وَفِلْقَةٌ دُونَهُ فَقَالَ لَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ اشْهَدُوا ‏\"‏ ‏.‏","This hadith has been transmitted on the authority of Abdullah b. Mas'ud (who said):We were along with Allah's Messenger (ﷺ) at Mina, that moon was split up into two. One of its parts was behind the mountain and the other one was on this side of the mountain. Allah's Messenger (may peace be upbn him) said to us: Bear witness to this","",""],[7073,7073,"2800.03","উবাইদুল্লাহ ইবনু মুআয আল আম্বারী (রহঃ) ..... ‘আবদুল্লাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সময় চন্দ্র ফেটে দু’টুকরো হয়ে যায়। এর এক টুকরোকে পাহাড় আড়াল করে ফেলেছে এবং অপর এক টুকরো পাহাড়ের উপর পরিলক্ষিত হয়েছে। তখন রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ হে আল্লাহ! তুমি সাক্ষী থাকো। (ইসলামিক ফাউন্ডেশন ৬৮১৬, ইসলামিক সেন্টার)","حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ أَبِي مَعْمَرٍ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ انْشَقَّ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم فِلْقَتَيْنِ فَسَتَرَ الْجَبَلُ فِلْقَةً وَكَانَتْ فِلْقَةٌ فَوْقَ الْجَبَلِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ اللَّهُمَّ اشْهَدْ ‏\"‏ ‏.‏","Abdullah b. Mas'ud reported that the moon was split up in two parts during the lifetime of Allah's Messenger (ﷺ). The mountain covered one of its parts and one part of it was above the mountain and Allah's Messenger (ﷺ) said:Bear witness to this","উবাইদুল্লাহ ইবনু মুআয আল আম্বারী (রহঃ) ..... ‘আবদুল্লাহ (রাযিঃ",""],[7074,7074,"2801.01","উবাইদুল্লাহ ইবনু মুআয (রহঃ) ..... ইবনু উমর (রাযিঃ) এর সানাদে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে হুবহু বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮১৭, ইসলামিক সেন্টার)","حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنِ الأَعْمَشِ، عَنْ مُجَاهِدٍ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم مِثْلَ ذَلِكَ ‏.‏","Another chain of transmitters reported the like of this hadith","",""],[7075,7075,"2801.02","(…/...) বিশর ইবনু খালিদ ও মুহাম্মাদ ইবনু বাশশার (রহঃ) ..... শুবাহ হতে অবিকল বর্ণনা করেছেন। তবে ইবনু আবু আদী (রহঃ) এর হাদীসের মধ্যে রয়েছে যে, তারপর তিনি বললেনঃ তোমরা সাক্ষী থাকো, তোমরা সাক্ষী থাকো। (ইসলামিক ফাউন্ডেশন ৬৮১৭, ইসলামিক সেন্টার)","وَحَدَّثَنِيهِ بِشْرُ بْنُ خَالِدٍ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، ح وَحَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، كِلاَهُمَا عَنْ شُعْبَةَ، بِإِسْنَادِ ابْنِ مُعَاذٍ عَنْ شُعْبَةَ، نَحْوَ حَدِيثِهِ غَيْرَ أَنَّ فِي، حَدِيثِ ابْنِ أَبِي عَدِيٍّ فَقَالَ ‏ \"‏ اشْهَدُوا اشْهَدُوا ‏\"‏ ‏.‏","This hadith has been transmitted on the authority of Shu'ba with a slight variation of wording","",""],[7076,7076,"","(…/...) মুহাম্মাদ ইবনু রাফি (রহঃ) ..... আনাস (রাযিঃ) হতে শাইবানের অবিকল হাদীস বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮১৮, ইসলামিক সেন্টার)","حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، وَعَبْدُ بْنُ حُمَيْدٍ، قَالاَ حَدَّثَنَا يُونُسُ بْنُ مُحَمَّدٍ، حَدَّثَنَا شَيْبَانُ، حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، أَنَّ أَهْلَ، مَكَّةَ سَأَلُوا رَسُولَ اللَّهِ صلى الله عليه وسلم أَنْ يُرِيَهُمْ آيَةً فَأَرَاهُمُ انْشِقَاقَ الْقَمَرِ مَرَّتَيْنِ ‏.‏ وَحَدَّثَنِيهِ مُحَمَّدُ بْنُ رَافِعٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، بِمَعْنَى حَدِيثِ شَيْبَانَ ‏.‏","Anas reported that the people of Mecca demanded from Allah's Messenger (ﷺ) that he should show them (some) signs (miracles) and he showed twice the splitting of the moon. This hadlth has been narrated on the authority of Anas through another chain of transmitters","",""],[7077,7077,"","(…/...) মুহাম্মাদ ইবনু রাফি (রহঃ) ..... আনাস (রাযিঃ) হতে শাইবানের অবিকল হাদীস বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮১৮, ইসলামিক সেন্টার)","حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، وَعَبْدُ بْنُ حُمَيْدٍ، قَالاَ حَدَّثَنَا يُونُسُ بْنُ مُحَمَّدٍ، حَدَّثَنَا شَيْبَانُ، حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، أَنَّ أَهْلَ، مَكَّةَ سَأَلُوا رَسُولَ اللَّهِ صلى الله عليه وسلم أَنْ يُرِيَهُمْ آيَةً فَأَرَاهُمُ انْشِقَاقَ الْقَمَرِ مَرَّتَيْنِ ‏.‏ وَحَدَّثَنِيهِ مُحَمَّدُ بْنُ رَافِعٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، بِمَعْنَى حَدِيثِ شَيْبَانَ ‏.‏","Anas reported that the people of Mecca demanded from Allah's Messenger (ﷺ) that he should show them (some) signs (miracles) and he showed twice the splitting of the moon. This hadlth has been narrated on the authority of Anas through another chain of transmitters","",""],[7078,7078,"2802.03","(…) মুহাম্মাদ ইবনুল মুসান্না ও ইবনু বাশশার (রহঃ) ..... আনাস (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, চাঁদ দু'টুকরো হয়েছে। তবে আবু দাউদ (রহঃ) এর হাদীসে রয়েছে, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সময় চাঁদ দু'টুকরো হয়েছে। (ইসলামিক ফাউন্ডেশন ৬৮১৯, ইসলামিক সেন্টার)","وَحَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، وَأَبُو دَاوُدَ ح وَحَدَّثَنَا ابْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، وَمُحَمَّدُ بْنُ جَعْفَرٍ، وَأَبُو دَاوُدَ كُلُّهُمْ عَنْ شُعْبَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، قَالَ انْشَقَّ الْقَمَرُ فِرْقَتَيْنِ ‏.‏ وَفِي حَدِيثِ أَبِي دَاوُدَ انْشَقَّ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏","Anas reported that the moon was split up in two parts and in the hadith recorded in Abu Dawud, the words are:\" The moon was split up into two parts during the life of Allah's Messenger (ﷺ)","…) মুহাম্মাদ ইবনুল মুসান্না ও ইবনু বাশশার (রহঃ) ..... আনাস (রাযিঃ",""],[7079,7079,"2803","মূসা ইবনু কুরায়শ আত তামীমী (রহঃ) ..... ইবনু আব্বাস (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সময় চাঁদ দু'টুকরো হয়েছে। (ইসলামিক ফাউন্ডেশন ৬৮২০, ইসলামিক সেন্টার)","حَدَّثَنَا مُوسَى بْنُ قُرَيْشٍ التَّمِيمِيُّ، حَدَّثَنَا إِسْحَاقُ بْنُ بَكْرِ بْنِ مُضَرَ، حَدَّثَنِي أَبِي، حَدَّثَنَا جَعْفَرُ بْنُ رَبِيعَةَ، عَنْ عِرَاكِ بْنِ مَالِكٍ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ إِنَّ الْقَمَرَ انْشَقَّ عَلَى زَمَانِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏","Ibn 'Abbas reported that the moon was split up during the lifetime of Allah's Messenger (may peace he upon him)","মূসা ইবনু কুরায়শ আত তামীমী (রহঃ) ..... ইবনু আব্বাস (রাযিঃ",""],[7080,7080,"","(…/...) মুহাম্মাদ ইবনু আবদুল্লাহ ইবনু নুমায়র ও আবু সাঈদ আল আশাজ্জ (রহঃ) ...... আবু মূসা (রাযিঃ) এর সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে হুবহু হাদীস বর্ণনা করেছেন। তবে হাদীসের মধ্যে وَيُجْعَلُ لَهُ الْوَلَدُ কথাটি উল্লেখ নেই। (ইসলামিক ফাউন্ডেশন ৬৮২২, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، وَأَبُو أُسَامَةَ عَنِ الأَعْمَشِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، عَنْ أَبِي مُوسَى، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لاَ أَحَدَ أَصْبَرُ عَلَى أَذًى يَسْمَعُهُ مِنَ اللَّهِ عَزَّ وَجَلَّ إِنَّهُ يُشْرَكُ بِهِ وَيُجْعَلُ لَهُ الْوَلَدُ ثُمَّ هُوَ يُعَافِيهِمْ وَيَرْزُقُهُمْ ‏\"‏ ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، وَأَبُو سَعِيدٍ الأَشَجُّ قَالاَ حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنَا سَعِيدُ بْنُ جُبَيْرٍ، عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ بِمِثْلِهِ إِلاَّ قَوْلَهُ ‏\"‏ وَيُجْعَلُ لَهُ الْوَلَدُ ‏\"‏ ‏.‏ فَإِنَّهُ لَمْ يَذْكُرْهُ ‏.‏","Abu Musa reported that Allah's Messenger (ﷺ) said:There is none to show more patience at listening to the most irksome things than Allah, the Exalted and Glorious. 'Partnership is associated to Him (polytheism), and (fatherhood) of a child is attributed to Him, but in spite of this He protects them (people) and provides them sustenance.' This hadith has been transmitted on the authority of Abu Musa with a slight variation of wording","",""],[7081,7081,"","(…/...) মুহাম্মাদ ইবনু আবদুল্লাহ ইবনু নুমায়র ও আবু সাঈদ আল আশাজ্জ (রহঃ) ...... আবু মূসা (রাযিঃ) এর সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে হুবহু হাদীস বর্ণনা করেছেন। তবে হাদীসের মধ্যে وَيُجْعَلُ لَهُ الْوَلَدُ কথাটি উল্লেখ নেই। (ইসলামিক ফাউন্ডেশন ৬৮২২, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، وَأَبُو أُسَامَةَ عَنِ الأَعْمَشِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، عَنْ أَبِي مُوسَى، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لاَ أَحَدَ أَصْبَرُ عَلَى أَذًى يَسْمَعُهُ مِنَ اللَّهِ عَزَّ وَجَلَّ إِنَّهُ يُشْرَكُ بِهِ وَيُجْعَلُ لَهُ الْوَلَدُ ثُمَّ هُوَ يُعَافِيهِمْ وَيَرْزُقُهُمْ ‏\"‏ ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، وَأَبُو سَعِيدٍ الأَشَجُّ قَالاَ حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنَا سَعِيدُ بْنُ جُبَيْرٍ، عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ بِمِثْلِهِ إِلاَّ قَوْلَهُ ‏\"‏ وَيُجْعَلُ لَهُ الْوَلَدُ ‏\"‏ ‏.‏ فَإِنَّهُ لَمْ يَذْكُرْهُ ‏.‏","Abu Musa reported that Allah's Messenger (ﷺ) said:There is none to show more patience at listening to the most irksome things than Allah, the Exalted and Glorious. 'Partnership is associated to Him (polytheism), and (fatherhood) of a child is attributed to Him, but in spite of this He protects them (people) and provides them sustenance.' This hadith has been transmitted on the authority of Abu Musa with a slight variation of wording","",""],[7082,7082,"2804.03","উবাইদুল্লাহ ইবনু সাঈদ (রহঃ) ..... ‘আবদুল্লাহ ইবনু কায়স (রাযিঃ) থেকে বর্ণিত। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেন, কষ্টকর কোন কথা শোনার পর আল্লাহর চেয়ে বেশি ধৈর্যশীল আর কেউ নেই। কেননা মানুষ আল্লাহর সঙ্গে অংশীদার স্থাপন করে এবং তার জন্য সন্তান সাব্যস্ত করে, এতদসত্ত্বেও তিনি তাদের জীবিকা নির্বাহ করেন, তাদেরকে মাফ করেন এবং তাদেরকে প্রয়োজনীয় সব কিছু প্রদান করেন। (ইসলামিক ফাউন্ডেশন ৬৮২৩, ইসলামিক সেন্টার)","وَحَدَّثَنِي عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنِ الأَعْمَشِ، حَدَّثَنَا سَعِيدُ بْنُ، جُبَيْرٍ عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، قَالَ قَالَ عَبْدُ اللَّهِ بْنُ قَيْسٍ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَا أَحَدٌ أَصْبَرَ عَلَى أَذًى يَسْمَعُهُ مِنَ اللَّهِ تَعَالَى إِنَّهُمْ يَجْعَلُونَ لَهُ نِدًّا وَيَجْعَلُونَ لَهُ وَلَدًا وَهُوَ مَعَ ذَلِكَ يَرْزُقُهُمْ وَيُعَافِيهِمْ وَيُعْطِيهِمْ ‏\"‏ ‏.‏","Abdullah b. Qais reported from Allah's Messenger (ﷺ) that none is more forbearing in listening to the most irksome things than Allah, the Exalted. They associate rivals with him, attribute sonhood to Him, but in spite of this He provides them sustenance, grants them safety, confers upon them so many things","উবাইদুল্লাহ ইবনু সাঈদ (রহঃ) ..... ‘আবদুল্লাহ ইবনু কায়স (রাযিঃ",""],[7083,7083,"2805.01","উবাইদুল্লাহ ইবনু মুআয আল আম্বারী (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ) এর সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে বর্ণিত। তিনি বলেন, জাহান্নামীদের মাঝে যার শাস্তি সবচেয়ে কম হবে, আল্লাহ তা’আলা তাকে বলবেন, পৃথিবী এবং পৃথিবীর মাঝে যা কিছু আছে সব কিছু যদি তোমার হয়ে যায়, তবে কি তুমি এসব কিছু মুক্তিপণ হিসেবে প্রদান করে নিজেকে আযাব থেকে রক্ষা করবে? সে বলবে, হ্যাঁ, অবশ্যই। তখন তিনি বলবেন, তুমি আদমের পৃষ্ঠে থাকা অবস্থায় আমি তো তোমার কাছে এর থেকেও সহজ জিনিস আশা করেছিলাম। তা হলো, তুমি শিরক করবে না। রাবী বলেন, আমার মনে হয়, তিনি বলেছেনঃ তাহলে আমি তোমাকে জাহান্নামে প্রবেশ করাব না। কিন্তু তুমি তা উপেক্ষা করে শিরকে জড়িয়ে পড়েছে। (ইসলামিক ফাউন্ডেশন ৬৮২৪, ইসলামিক সেন্টার)","حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي عِمْرَانَ الْجَوْنِيِّ، عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لأَهْوَنِ أَهْلِ النَّارِ عَذَابًا لَوْ كَانَتْ لَكَ الدُّنْيَا وَمَا فِيهَا أَكُنْتَ مُفْتَدِيًا بِهَا فَيَقُولُ نَعَمْ فَيَقُولُ قَدْ أَرَدْتُ مِنْكَ أَهْوَنَ مِنْ هَذَا وَأَنْتَ فِي صُلْبِ آدَمَ أَنْ لاَ تُشْرِكَ - أَحْسَبُهُ قَالَ - وَلاَ أُدْخِلَكَ النَّارَ فَأَبَيْتَ إِلاَّ الشِّرْكَ ‏\"‏ ‏.‏","Anas b. Malik reported Allah's Messenger (ﷺ) as saying:Allah, the Exalted and High, would say to one who shall have to undergo the least torture (on the Day of Resurrection): Would you like to go as ransom if you had all worldly riches; he would say: Yes. Allah would say to him: When you were in the loins of Adam, I demanded from you something easier than this that you should not associate anything with Me. (The narrator says): I think He also said: I would not cause you to enter Hell-Fire but you defied and attributed Divinity (to others besides Me)","",""],[7084,7084,"2805.02","(…/…) মুহাম্মদ ইবনু বাশার (রহ:) ...... আনাস ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। তিনি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে অবিকল বর্ণনা করেছেন। তবে তিনি وَلاَ أُدْخِلَكَ النَّارَ কথাটি উল্লেখ করেননি। (ইসলামিক ফাউন্ডেশন ৬৮২৫, ইসলামিক সেন্টার)","حَدَّثَنَاهُ مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدٌ، - يَعْنِي ابْنَ جَعْفَرٍ - حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي عِمْرَانَ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ، يُحَدِّثُ عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِهِ إِلاَّ قَوْلَهُ ‏ \"‏ وَلاَ أُدْخِلَكَ النَّارَ ‏\"‏ ‏.‏ فَإِنَّهُ لَمْ يَذْكُرْهُ ‏.‏","This hadith has been narrated on the authority of Anas b. Malik through another chain of transmitters, but with a slight variation of wording (and the words are):I shall cause him to enter Hell.\" (The words subsequent to these) have not been mentioned","…/…) মুহাম্মদ ইবনু বাশার (রহ:) ...... আনাস ইবনু মালিক (রাযিঃ",""],[7085,7085,"2805.03","উবাইদুল্লাহ ইবনু আল কাওয়ারিরী, ইসহাক ইবনু ইবরাহীম, মুহাম্মাদ ইবনুল মুসান্না ও ইবনু বাশশার (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেন, কিয়ামতের দিন কাফিরদেরকে বলা হবে, তুমি কি বলো, যদি তুমি পৃথিবী সমতুল্য স্বর্ণের মালিক হও, তাহলে মুক্তিপণ হিসেবে তা প্রদান করে তুমি কি নিজেকে শাস্তি হতে রক্ষা করবে? সে বলবে, হ্যাঁ অবশ্যই। তখন তাকে বলা হবে, তোমার নিকট হতে তো এর থেকে অধিক সহজ বিষয় কামনা করা হয়েছিল। (ইসলামিক ফাউন্ডেশন ৬৮২৬, ইসলামিক সেন্টার)","حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، وَمُحَمَّدُ بْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ قَالَ إِسْحَاقُ أَخْبَرَنَا وَقَالَ الآخَرُونَ، حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، حَدَّثَنَا أَبِي، عَنْ قَتَادَةَ، حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏ \"‏ يُقَالُ لِلْكَافِرِ يَوْمَ الْقِيَامَةِ أَرَأَيْتَ لَوْ كَانَ لَكَ مِلْءُ الأَرْضِ ذَهَبًا أَكُنْتَ تَفْتَدِي بِهِ فَيَقُولُ نَعَمْ ‏.‏ فَيُقَالُ لَهُ قَدْ سُئِلْتَ أَيْسَرَ مِنْ ذَلِكَ ‏\"‏ ‏.‏","Anas b. Malik reported that Allah's Messenger (may peace be u n him) said:It would be said to the non-believers on the Day of Resurrection: If you were to possess gold, filling the whole earth, would you like to secure your freedom by paying that? He would say: Yes. Thereupon it would be said to him: Something easier (than this) was demanded from you (but you paid no heed to it)","",""],[7086,7086,"2805.04","আবদ ইবনু হুমায়দ ও আম্বর ইবনু যুবরাহ (রহঃ) .... আনাস (রাযিঃ) এর সানদে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে অবিকল হাদীস বর্ণনা করেছেন। তবে এতে রয়েছে যে, তাকে বলা হবে, তুমি মিথ্যা বলেছ। তোমার কাছে তো এর থেকে সহজ বিষয় কামনা করা হয়েছিল। (ইসলামিক ফাউন্ডেশন ৬৮২৭, ইসলামিক সেন্টার)","وَحَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا رَوْحُ بْنُ عُبَادَةَ، ح وَحَدَّثَنِي عَمْرُو بْنُ زُرَارَةَ، أَخْبَرَنَا عَبْدُ الْوَهَّابِ، - يَعْنِي ابْنَ عَطَاءٍ - كِلاَهُمَا عَنْ سَعِيدِ بْنِ أَبِي عَرُوبَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِهِ غَيْرَ أَنَّهُ قَالَ ‏ \"‏ فَيُقَالُ لَهُ كَذَبْتَ قَدْ سُئِلْتَ مَا هُوَ أَيْسَرُ مِنْ ذَلِكَ ‏\"‏ ‏.‏","Anas reported this hadlth through another chain of transmitters and the words are:\" It would be said to him: You have told a lie; what had been demanded from you was quite easier than this (the belief in the Oneness of Allah)","",""],[7087,7087,"2806","যুহায়র ইবনু হারব ও আবদ ইবনু হুমায়দ (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, এক লোক জিজ্ঞেস করল, হে আল্লাহর রসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম! কিয়ামত দিবসে কাফিরদেরকে নিম্নমুখী করে কিরূপে উথিত হবে? তিনি বললেন, যিনি দুনিয়াতে উভয় পায়ের উপর ভর করে চালিত করেছেন, তিনি কি কিয়ামতের দিন তাদেরকে মুখের উপর ভর করে চালাতে সক্ষম হবেন না? এ হাদীস শুনে কাতাদাহ্ বললেন, আমার রবের মর্যাদার শপথ অবশ্যই তিনি সক্ষম হবেন। (ইসলামিক ফাউন্ডেশন ৬৮২৮, ইসলামিক সেন্টার)","حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، وَعَبْدُ بْنُ حُمَيْدٍ، - وَاللَّفْظُ لِزُهَيْرٍ - قَالاَ حَدَّثَنَا يُونُسُ، بْنُ مُحَمَّدٍ حَدَّثَنَا شَيْبَانُ، عَنْ قَتَادَةَ، حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ، أَنَّ رَجُلاً، قَالَ يَا رَسُولَ اللَّهِ كَيْفَ يُحْشَرُ الْكَافِرُ عَلَى وَجْهِهِ يَوْمَ الْقِيَامَةِ قَالَ ‏ \"‏ أَلَيْسَ الَّذِي أَمْشَاهُ عَلَى رِجْلَيْهِ فِي الدُّنْيَا قَادِرًا عَلَى أَنْ يُمْشِيَهُ عَلَى وَجْهِهِ يَوْمَ الْقِيَامَةِ ‏\"‏ ‏.‏ قَالَ قَتَادَةُ بَلَى وَعِزَّةِ رَبِّنَا ‏.‏","Anas b. Malik reported that a person said:Allah's Messenger, how the non-believers be made to assemble on the Day of Resurrection (by crawling) on their faces? Thereupon he said: Is He Who is powerful to make them walk on their feet not powerful enough to make them (crawl) upon their faces on the Day of Resurrection? Qatada said: Of course, it is so. (He adjured): By the might of our Lord","যুহায়র ইবনু হারব ও আবদ ইবনু হুমায়দ (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ",""],[7088,7088,"2807","‘আমর আন নাকিদ (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ জাহান্নামের উপযোগী-দুনিয়ায় সর্বাধিক সচ্ছল ও ধন-সম্পদের অধিকার লোককে কিয়ামতের দিন উপস্থিত করা হবে। এরপর তাকে জাহান্নামের আগুনে একবার অবগাহন করিয়ে বলা হবে, হে আদম সন্তান! দুনিয়াতে আরাম-আয়েশ কখনো তুমি ভোগ করেছে কি? কখনো তুমি স্বাচ্ছদ্য অবস্থায় দিন অতিবাহিত করেছে কি? সে বলবে, আল্লাহর শপথ হে আমার প্রতিপালক না, কক্ষনো করিনি। এরপর জান্নাতের উপযোগী দুনিয়ায় সর্বাধিক দুরাবস্থা সম্পন্ন লোককে আনা হবে। এরপর তাকে জান্নাতে একবার অবগাহন করিয়ে জিজ্ঞেস করা হবে, হে আদম সন্তান! কখনো তুমি কষ্টে দিনাতিপাত করেছে কি? হৃদয় বিদারক এবং ভয়াবহ অবস্থায় দিনাতিপাত করেছে কি? সে বলবে, আল্লাহর কসম, হে আমার প্রতিপালক! কক্ষনো আমি কষ্টের সাথে দিনাতিপাত করিনি এবং দুঃখ কক্ষনো দেখিনি। (ইসলামিক ফাউন্ডেশন ৬৮২৯, ইসলামিক সেন্টার)","حَدَّثَنَا عَمْرٌو النَّاقِدُ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، أَخْبَرَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ ثَابِتٍ، الْبُنَانِيِّ عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ يُؤْتَى بِأَنْعَمِ أَهْلِ الدُّنْيَا مِنْ أَهْلِ النَّارِ يَوْمَ الْقِيَامَةِ فَيُصْبَغُ فِي النَّارِ صَبْغَةً ثُمَّ يُقَالُ يَا ابْنَ آدَمَ هَلْ رَأَيْتَ خَيْرًا قَطُّ هَلْ مَرَّ بِكَ نَعِيمٌ قَطُّ فَيَقُولُ لاَ وَاللَّهِ يَا رَبِّ ‏.‏ وَيُؤْتَى بِأَشَدِّ النَّاسِ بُؤْسًا فِي الدُّنْيَا مِنْ أَهْلِ الْجَنَّةِ فَيُصْبَغُ صَبْغَةً فِي الْجَنَّةِ فَيُقَالُ لَهُ يَا ابْنَ آدَمَ هَلْ رَأَيْتَ بُؤْسًا قَطُّ هَلْ مَرَّ بِكَ شِدَّةٌ قَطُّ فَيَقُولُ لاَ وَاللَّهِ يَا رَبِّ مَا مَرَّ بِي بُؤُسٌ قَطُّ وَلاَ رَأَيْتُ شِدَّةً قَطُّ ‏\"‏ ‏.‏","Anas b. Malik reported that Allah's Messenger (ﷺ) said that one amongst the denizens of Hell who had led a life of ease and plenty amongst the people of the world would be made to dip in Fire only once on the Day of Resurrection and then it would be said to him:O, son of Adam, did you find any comfort, did you happen to get any material blessing? He would say: By Allah, no, my Lord. And then that person from amongst the persons of the world be brought who had led the most miserable life (in the world) from amongst the inmates of Paradise. and he would be made to dip once in Paradise and it would be said to him. 0, son of Adam, did you face, any hardship? Or had any distress fallen to your lot? And he would say: By Allah, no,0 my Lord, never did I face any hardship or experience any distress","আমর আন নাকিদ (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ",""],[7089,7089,"2808.01","আবূ বাকর ইবনু আবূ শাইবাহ ও যুহায়র ইবনু হারব (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ একটি নেকীর ক্ষেত্রেও আল্লাহ তা’আলা কোন মুমিন বান্দার প্রতি অত্যাচার করবেন না। বরং তিনি এর ফলাফল দুনিয়াতে দান করবেন এবং আখিরাতেও দান করবেন। আর কাফির লোক পার্থিব জগতে আল্লাহর উদ্দেশে যে সৎ ‘আমল করে এর প্রতিদান স্বরূপ তিনি তাকে জীবিকা নির্বাহ করেন। পরিশেষে আখিরাতে প্রতিফল দেয়ার মতো তার কাছে কোন সৎ আমলই থাকবে না। (ইসলামিক ফাউন্ডেশন ৬৮৩০, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَزُهَيْرُ بْنُ حَرْبٍ، - وَاللَّفْظُ لِزُهَيْرٍ - قَالاَ حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، أَخْبَرَنَا هَمَّامُ بْنُ يَحْيَى، عَنْ قَتَادَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ إِنَّ اللَّهَ لاَ يَظْلِمُ مُؤْمِنًا حَسَنَةً يُعْطَى بِهَا فِي الدُّنْيَا وَيُجْزَى بِهَا فِي الآخِرَةِ وَأَمَّا الْكَافِرُ فَيُطْعَمُ بِحَسَنَاتِ مَا عَمِلَ بِهَا لِلَّهِ فِي الدُّنْيَا حَتَّى إِذَا أَفْضَى إِلَى الآخِرَةِ لَمْ تَكُنْ لَهُ حَسَنَةٌ يُجْزَى بِهَا ‏\"‏ ‏.‏","Anas b. Malik reported that Allah's Messenger (ﷺ) said:Verily, Allah does not treat a believer unjustly in regard to his virtues. He would confer upon him (His blessing) in this world and would give him reward in the Hereafter. And as regards a non-believer, he would be made to taste the reward (of virtue in this world) what he has done for himself so much that when it would be the Hereafter, he would find no virtue for which he should be rewarded","আবূ বাকর ইবনু আবূ শাইবাহ ও যুহায়র ইবনু হারব (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ",""],[7090,7090,"2808.02","আসিম ইবনু নাযর আত তামীমী (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। তিনি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে রিওয়ায়াত করেছেন যে, কাফির যদি দুনিয়াতে কোন সৎ আমল করে তবে এর প্রতিদান স্বরূপ দুনিয়াতেই তাকে জীবনোপকরণ প্রদান করা হয়ে থাকে। আর মুমিনদের নেকী আল্লাহ তা’আলা আখিরাতের জন্য জমা করে রেখে দেন এবং আনুগত্যের প্রতিফল স্বরূপ আল্লাহ তা’আলা তাদেরকে পৃথিবীতেও জীবিকা নির্বাহ করে থাকেন। (ইসলামিক ফাউন্ডেশন ৬৮৩১, ইসলামিক সেন্টার)","حَدَّثَنَا عَاصِمُ بْنُ النَّضْرِ التَّيْمِيُّ، حَدَّثَنَا مُعْتَمِرٌ، قَالَ سَمِعْتُ أَبِي، حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ حَدَّثَ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏ \"‏ إِنَّ الْكَافِرَ إِذَا عَمِلَ حَسَنَةً أُطْعِمَ بِهَا طُعْمَةً مِنَ الدُّنْيَا وَأَمَّا الْمُؤْمِنُ فَإِنَّ اللَّهَ يَدَّخِرُ لَهُ حَسَنَاتِهِ فِي الآخِرَةِ وَيُعْقِبُهُ رِزْقًا فِي الدُّنْيَا عَلَى طَاعَتِهِ ‏\"‏ ‏.‏","Anas b. Malik reported that Allah's Messenger (ﷺ) thus told him:When a non-believer does good he is made to taste Its reward in this world. And so far as the believer is concerned, Allah stores (the reward) of his virtues for the Hereafter and provides him sustenance in accordance with his obedience to Him","আসিম ইবনু নাযর আত তামীমী (রহঃ) ..... আনাস ইবনু মালিক (রাযিঃ",""],[7091,7091,"2808.03","মুহাম্মাদ ইবনু আবদুল্লাহ আর রুয্‌য়ী (রহঃ) ..... আনাস (রাযিঃ) এর সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে অবিকল বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮৩২, ইসলামিক সেন্টার)","حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرُّزِّيُّ، أَخْبَرَنَا عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ، عَنْ سَعِيدٍ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمَعْنَى حَدِيثِهِمَا ‏.‏","This hadith has been narrated on the authority of Anas b. Malik through another chain of transmitters","",""],[7092,7092,"2809.01","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ মুমিনের দৃষ্টান্ত শস্যক্ষেতের মতো। বাতাস সবসময় তাকে আন্দোলিত করে। অনুরূপভাবে মুমিনের উপরও সবসময় বিপদাপদ আসতে থাকে। আর মুনাফিকের দৃষ্টান্ত দেবদারু গাছের মতো। মূল উৎপাটন হয়ে যায়; কিন্তু সেটা আন্দোলিত হয় না। (ইসলামিক ফাউন্ডেশন ৬৮৩৩, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ الأَعْلَى، عَنْ مَعْمَرٍ، عَنِ الزُّهْرِيِّ، عَنْ سَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَثَلُ الْمُؤْمِنِ كَمَثَلِ الزَّرْعِ لاَ تَزَالُ الرِّيحُ تُمِيلُهُ وَلاَ يَزَالُ الْمُؤْمِنُ يُصِيبُهُ الْبَلاَءُ وَمَثَلُ الْمُنَافِقِ كَمَثَلِ شَجَرَةِ الأَرْزِ لاَ تَهْتَزُّ حَتَّى تَسْتَحْصِدَ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:The Similitude of a believer is that of (a standing) crop which the air continues to toss from one side to another; in the same way a believer always (receives the strokes) of misfortune. The similitude of a hypocrite is that of a cypress tree which does not move until it is uprooted","আবূ বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ",""],[7093,7093,"2809.02","মুহাম্মাদ ইবনু রাফি ও আবদ ইবনু হুমায়দ (রহঃ) ..... যুহরী (রহঃ) থেকে এ সূত্রে অবিকল হাদীস বর্ণনা করেছেন। তবে আবদুর রাযযাক এর হাদীসে تُمِيلُهُ এর স্থলে تُفِيئُهُ উল্লেখ রয়েছে (উভয়ের অর্থ একই, অর্থাৎ আন্দোলিত করে)। (ইসলামিক ফাউন্ডেশন ৬৮৩৪, ইসলামিক সেন্টার)","حَدَّثَنَا مُحَمَّدُ بْنُ رَافِعٍ، وَعَبْدُ بْنُ حُمَيْدٍ، عَنْ عَبْدِ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، بِهَذَا الإِسْنَادِ غَيْرَ أَنَّ فِي، حَدِيثِ عَبْدِ الرَّزَّاقِ مَكَانَ قَوْلِهِ تُمِيلُهُ ‏ \"‏ تُفِيئُهُ ‏\"‏ ‏.‏","This hadith has been narrated on the authority of Zuhri with the same chain of transmitters, but with a slight variation of wording","",""],[7094,7094,"2810.01","আবু বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... কা'ব ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ মু'মিনের দৃষ্টান্ত নরম চারাগাছের মতো। বাতাস সেটাকে দুলাতে থাকে কখনো তাকে নুইয়ে ফেলে আবার কখনো একেবারে সোজা করে ফেলে। এমনিভাবে অবশেষে সেটা পূর্ণতা লাভ করে শুকিয়ে যায়। আর কাফিরদের দৃষ্টান্ত হচ্ছে স্বীয় কাণ্ডে দাঁড়ানো দেবদার গাছের মতো। কোন কিছুই তাকে নাড়াতে পারে না। কিন্তু এটা একেবারেই মূলোৎপাটিত হয়ে যায়। (ইসলামিক ফাউন্ডেশন ৬৮৩৫, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ نُمَيْرٍ، وَمُحَمَّدُ بْنُ بِشْرٍ، قَالاَ حَدَّثَنَا زَكَرِيَّاءُ بْنُ أَبِي زَائِدَةَ، عَنْ سَعْدِ بْنِ إِبْرَاهِيمَ، حَدَّثَنِي ابْنُ كَعْبِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، كَعْبٍ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَثَلُ الْمُؤْمِنِ كَمَثَلِ الْخَامَةِ مِنَ الزَّرْعِ تُفِيئُهَا الرِّيحُ وَتَصْرَعُهَا مَرَّةً وَتَعْدِلُهَا أُخْرَى حَتَّى تَهِيجَ وَمَثَلُ الْكَافِرِ كَمَثَلِ الأَرْزَةِ الْمُجْذِيَةِ عَلَى أَصْلِهَا لاَ يُفِيئُهَا شَىْءٌ حَتَّى يَكُونَ انْجِعَافُهَا مَرَّةً وَاحِدَةً ‏\"‏ ‏.‏","Ka'b reported that Allah's Messenger (ﷺ) said that the similitude of a believer is that of a standing crop in a field which is shaken by wind and then it comes to its original position but it stands at its roots. The similitude of a non-believer is that of a cypress tree which stands on its roots and nothing shakes it but it is uprooted (with) one (violent stroke)","আবু বাকর ইবনু আবূ শাইবাহ্ (রহঃ) ..... কা'ব ইবনু মালিক (রাযিঃ",""],[7095,7095,"2810.02","যুহায়র ইবনু হারব (রহঃ) ..... কা'ব ইবনু মালিক (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ মুমিনের দৃষ্টান্ত নরম চারাগাছের মতো। বাতাস তাকে আন্দোলিত করে। বাতাস কখনো তাকে নুইয়ে দেয়, আবার কখনো একেবারে সোজা দাঁড় করিয়ে দেয়। এমনি করে তার মৃত্যুক্ষণ এসে উপস্থিত হয়। আর মুনাফিকের দৃষ্টান্ত দাঁড়ানো দেবদারু গাছের মতো, কোন কিছুই তাকে নত করতে পারে না। পরিশেষে তাকে একেবারেই মূলোচ্ছেদ করে দেয়। (ইসলামিক ফাউন্ডেশন ৬৮৩৬, ইসলামিক সেন্টার ৬৮৯১[ক)","حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا بِشْرُ بْنُ السَّرِيِّ، وَعَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، قَالاَ حَدَّثَنَا سُفْيَانُ، عَنْ سَعْدِ بْنِ إِبْرَاهِيمَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَثَلُ الْمُؤْمِنِ كَمَثَلِ الْخَامَةِ مِنَ الزَّرْعِ تُفِيئُهَا الرِّيَاحُ تَصْرَعُهَا مَرَّةً وَتَعْدِلُهَا حَتَّى يَأْتِيَهُ أَجَلُهُ وَمَثَلُ الْمُنَافِقِ مَثَلُ الأَرْزَةِ الْمُجْذِيَةِ الَّتِي لاَ يُصِيبُهَا شَىْءٌ حَتَّى يَكُونَ انْجِعَافُهَا مَرَّةً وَاحِدَةً ‏\"‏ ‏.‏","Ka'b b. Malik reported on the authority of his father that the similitude of a believer is that of a standing crop. The wind sometimes shakes it and sometimes raises it up and then it comes to its destined end. And the similitude of a hypocrite is that of a cypress tree which is not affected by anything but is uprooted once for all","যুহায়র ইবনু হারব (রহঃ) ..... কা'ব ইবনু মালিক (রাযিঃ",""],[7096,7096,"2810.03","মুহাম্মাদ ইবনু হাতিম ও মাহমুদ ইবনু গাইলান (রহঃ) ..... কা'ব ইবনু মালিক (রাযিঃ) থেকে বর্ণিত তিনি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে বর্ণনা করেছেন। তবে মাহমুদ এর রিওয়ায়াতে বিশর এর সূত্রে বর্ণিত আছে, مَثَلُ الْكَافِرِ كَمَثَلِ الأَرْزَةِ কাফরের দৃষ্টান্ত দেবদারু গাছের মতো। আর ইবনু হাতিম (রাযিঃ) যুহায়র এর ন্যায় مَثَلُ الْمُنَافِقِ অর্থাৎ- মুনাফিকের দৃষ্টাস্তের কথাটি বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮৩৬, ইসলামিক সেন্টার)","وَحَدَّثَنِيهِ مُحَمَّدُ بْنُ حَاتِمٍ، وَمَحْمُودُ بْنُ غَيْلاَنَ، قَالاَ حَدَّثَنَا بِشْرُ بْنُ السَّرِيِّ، حَدَّثَنَا سُفْيَانُ، عَنْ سَعْدِ بْنِ إِبْرَاهِيمَ، عَنْ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم غَيْرَ أَنَّ مَحْمُودًا قَالَ فِي رِوَايَتِهِ عَنْ بِشْرٍ ‏\"‏ وَمَثَلُ الْكَافِرِ كَمَثَلِ الأَرْزَةِ ‏\"‏ ‏.‏ وَأَمَّا ابْنُ حَاتِمٍ فَقَالَ ‏\"‏ مَثَلُ الْمُنَافِقِ ‏\"‏ ‏.‏ كَمَا قَالَ زُهَيْرٌ ‏.‏","This hadith has been narrated through a couple of other chains of transmitters, one which says \"the similitude of the disbeliever\" instead and another which agrees with the wording of the previous hadith","মুহাম্মাদ ইবনু হাতিম ও মাহমুদ ইবনু গাইলান (রহঃ) ..... কা'ব ইবনু মালিক (রাযিঃ",""],[7097,7097,"2810.04","মুহাম্মাদ ইবনু বাশশার ও আবদুল্লাহ ইবনু হাশিম (রহঃ) ..... কা'ব ইবনু মালিক (রাযিঃ) এর সানাদে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে তাদের অবিকল হাদীস বর্ণনা করেছেন। কিন্তু তারা দু’জনেই ইয়াহইয়া (রহঃ) হতে বর্ণনা করেছেন যে, কফিরের দৃষ্টান্ত দেবদারু গাছের মতো। (ইসলামিক ফাউন্ডেশন ৬৮৩৭, ইসলামিক সেন্টার)","وَحَدَّثَنَاهُ مُحَمَّدُ بْنُ بَشَّارٍ، وَعَبْدُ اللَّهِ بْنُ هَاشِمٍ، قَالاَ حَدَّثَنَا يَحْيَى، - وَهُوَ الْقَطَّانُ - عَنْ سُفْيَانَ، عَنْ سَعْدِ بْنِ إِبْرَاهِيمَ، - قَالَ ابْنُ هَاشِمٍ عَنْ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، وَقَالَ ابْنُ بَشَّارٍ، عَنِ ابْنِ كَعْبِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، - عَنِ النَّبِيِّ صلى الله عليه وسلم بِنَحْوِ حَدِيثِهِمْ وَقَالاَ جَمِيعًا فِي حَدِيثِهِمَا عَنْ يَحْيَى، ‏ \"‏ وَمَثَلُ الْكَافِرِ مَثَلُ الأَرْزَةِ ‏\"‏ ‏.‏","This hadith has been narrated on the authority of Ibn Ka'b through another chain of transmitters but with \" \"the similitude of the disbeliever is that of a cypress tree","",""],[7098,7098,"2811.01","ইয়াহইয়া ইবনু আইয়্যুব, কুতাইবাহ ইবনু সাঈদ ও আলী ইবনু হুজর আস্ সাদী (রহঃ) ..... ‘আবদুল্লাহ ইবনু উমর (রাযিঃ) থেকে বর্ণিত। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেন, গাছ-গাছালির মধ্যে এমন একটি গাছ আছে, যার পাতা ঝরে পড়ে না এবং তা হলো মুমিনের দৃষ্টান্ত। তোমরা আমাকে বলতে পার, সেটা কোন গাছ? তারপর লোকজনের ধারণা জঙ্গলের কোন গাছের প্রতি নিবদ্ধ হল। আবদুল্লাহ (রাযিঃ) বলেন, আমার মনে হতে লাগল যে, তা হলো খর্জুর বৃক্ষ। কিন্তু আমি লজ্জাবোধ করলাম। সহাবায়ে কিরাম (রাযিঃ) বললেন, হে আল্লাহর রসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম! আপনিই আমাদের তা বলে দিন। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ তা হলো খর্জুর বৃক্ষ। ‘আবদুল্লাহ (রাযিঃ) বলেন, এরপর আমি আমার পিতাকে আমার মনে যা এসেছিল তা বললাম। তিনি বললেন, তুমি যদি তখন তা বলে দিতে যে, সেটা হলো খর্জুর বৃক্ষ, তবে আমি অমুক অমুক জিনিস লাভ করার চাইতেও অধিক খুশী হতাম। (ইসলামিক ফাউন্ডেশন ৬৮৩৮, ইসলামিক সেন্টার)","حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، وَعَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ، - وَاللَّفْظُ لِيَحْيَى - قَالُوا حَدَّثَنَا إِسْمَاعِيلُ، - يَعْنُونَ ابْنَ جَعْفَرٍ - أَخْبَرَنِي عَبْدُ اللَّهِ بْنُ دِينَارٍ، أَنَّهُ سَمِعَ عَبْدَ، اللَّهِ بْنَ عُمَرَ يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ مِنَ الشَّجَرِ شَجَرَةً لاَ يَسْقُطُ وَرَقُهَا وَإِنَّهَا مَثَلُ الْمُسْلِمِ فَحَدِّثُونِي مَا هِيَ ‏\"‏ ‏.‏ فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَوَادِي ‏.‏ قَالَ عَبْدُ اللَّهِ وَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ فَاسْتَحْيَيْتُ ثُمَّ قَالُوا حَدِّثْنَا مَا هِيَ يَا رَسُولَ اللَّهِ قَالَ فَقَالَ ‏\"‏ هِيَ النَّخْلَةُ ‏\"‏ ‏.‏ قَالَ فَذَكَرْتُ ذَلِكَ لِعُمَرَ قَالَ لأَنْ تَكُونَ قُلْتَ هِيَ النَّخْلَةُ أَحَبُّ إِلَىَّ مِنْ كَذَا وَكَذَا ‏.‏","Abdullah b. Umar reported that Allah's Messenger (ﷺ) said:There is a tree amongst trees, the leaves of which do not wither and that is like a Muslim; tell me which that (tree) can be? The people began to think of the trees of the forest. Abdullah said: I thought that it could be the date-palm tree, but I felt hesitant (to say that). They (the Companions) then said: Allah's Messenger, (kindly) tell us which that can be? Thereupon he said: It is the date-palm tree. I made a mention of that to 'Umar, whereupon he said: Had you said that it meant the date-palin tree, this statement of yours (would have been dearer to me) than such and such things","",""],[7099,7099,"2811.02","(…) মুহাম্মাদ ইবনু উবাইদুল্লাহ আল গুবারী (রহঃ) ..... ইবনু উমার (রাযিঃ) থেকে বর্ণিত। একদা রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার সহাবাগণকে বললেন, এমন একটি গাছ আছে, যার দৃষ্টান্ত মুমিনের মতো, এ গাছটি কি গাছ, তোমরা কি আমাকে বলতে পার? তখন লোকেরা জঙ্গলের গাছসমূহ থেকে এক একটি গাছের কথা বর্ণনা করল। ইবনু উমার (রাযিঃ) বলেন, আমার মনে হতে লাগল, তা হলো খেজুর গাছ। তখন আমি বলার ইচ্ছা করলাম। কিন্তু সেখানে যেহেতু সমাজের বয়োবৃদ্ধ ব্যক্তিগণও ছিলেন, তাই আমি কথা বলতে ভয় পাচ্ছিলাম। লোকজন চুপ হলে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেন, তা হলো খেজুর গাছ। (ইসলামিক ফাউন্ডেশন ৬৮৩৯, ইসলামিক সেন্টার)","حَدَّثَنِي مُحَمَّدُ بْنُ عُبَيْدٍ الْغُبَرِيُّ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، حَدَّثَنَا أَيُّوبُ، عَنْ أَبِي الْخَلِيلِ، الضُّبَعِيِّ عَنْ مُجَاهِدٍ، عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَوْمًا لأَصْحَابِهِ ‏\"‏ أَخْبِرُونِي عَنْ شَجَرَةٍ مَثَلُهَا مَثَلُ الْمُؤْمِنِ ‏\"‏ ‏.‏ فَجَعَلَ الْقَوْمُ يَذْكُرُونَ شَجَرًا مِنْ شَجَرِ الْبَوَادِي ‏.‏ قَالَ ابْنُ عُمَرَ وَأُلْقِيَ فِي نَفْسِي أَوْ رُوعِيَ أَنَّهَا النَّخْلَةُ فَجَعَلْتُ أُرِيدُ أَنْ أَقُولَهَا فَإِذَا أَسْنَانُ الْقَوْمِ فَأَهَابُ أَنْ أَتَكَلَّمَ فَلَمَّا سَكَتُوا قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ هِيَ النَّخْلَةُ ‏\"‏ ‏.‏","Ibn Umar reported that Allah's Messenger (ﷺ) one day said to his Companions:Tell me about a tree which has resemblance with a believer. The people began to mention (different) trees of the forest. Ibn 'Umar said: It was instilled in my mind or in my heart and it stuck therein that it implied the date- palm tree. I made up my mind to make a mention of that but could not do that because of the presence of the elderly people there. When there was a hush amongst them (after they had expressed their views), Allah's Messenger (ﷺ) said: It Is the date-palm tree","…) মুহাম্মাদ ইবনু উবাইদুল্লাহ আল গুবারী (রহঃ) ..... ইবনু উমার (রাযিঃ",""],[7100,7100,"2811.03","আবূ বাকর ইবনু আবূ শাইবাহ ও ইবনু আবূ উমার (রহঃ) ..... মুজাহিদ (রহঃ) থেকে বর্ণিত। তিনি বলেন, আমি মাদীনায় ইবনু উমর (রাযিঃ) এর সাথে ছিলাম। একটি হাদীস ছাড়া রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে কোন হাদীস বর্ণনা করতে তাকে আমি শুনিনি। তিনি বলেন, আমরা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সাথে বসা ছিলাম। তখন তার নিকট খেজুর গাছের মাথি আনা হলো। তারপর তিনি পূর্বোক্ত হাদীস দুটোর মতো এ হাদীসটি বর্ণনা করলেন। (ইসলামিক ফাউন্ডেশন ৬৮৪০, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَابْنُ أَبِي عُمَرَ، قَالاَ حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، قَالَ صَحِبْتُ ابْنَ عُمَرَ إِلَى الْمَدِينَةِ فَمَا سَمِعْتُهُ يُحَدِّثُ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم إِلاَّ حَدِيثًا وَاحِدًا قَالَ كُنَّا عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَأُتِيَ بِجُمَّارٍ ‏.‏ فَذَكَرَ بِنَحْوِ حَدِيثِهِمَا ‏.‏","Mujahid said:(I have had the privilege) of accompanying Ibn 'Umar up to Medina but I did not hear him narrate anything from Allah's Messenger (ﷺ) except one hadith. And he said: We were in the presence of Allah's Messenger (ﷺ) that there was brought to him the kernel of a date. The rest of the hadith is the same","আবূ বাকর ইবনু আবূ শাইবাহ ও ইবনু আবূ উমার (রহঃ) ..... মুজাহিদ (রহঃ",""],[7101,7101,"2811.04","ইবনু নুমায়র (রহঃ) ..... মুজাহিদ (রহঃ) থেকে বর্ণিত। তিনি বলেন, আমি ইবনু উমার (রাযিঃ) কে বলতে শুনেছি যে, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর কাছে খেজুর গাছের মাথি আনা হলো। তারপর তিনি পূর্বোক্তদের অবিকল হাদীস বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮৪১, ইসলামিক সেন্টার)","وَحَدَّثَنَا ابْنُ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا سَيْفٌ، قَالَ سَمِعْتُ مُجَاهِدًا، يَقُولُ سَمِعْتُ ابْنَ، عُمَرَ يَقُولُ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِجُمَّارٍ ‏.‏ فَذَكَرَ نَحْوَ حَدِيثِهِمْ ‏.‏","Mujahid reported:I heard Ibn 'Umar as saying: There was brought to Allah's Messenger (ﷺ) the kernel. The rest of the hadith is tile same","ইবনু নুমায়র (রহঃ) ..... মুজাহিদ (রহঃ",""],[7102,7102,"2811.05","আবূ বাকর ইবনু আবূ শাইবাহ (রহঃ) ..... ইবনু উমর (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমরা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর নিকট উপবিষ্ট ছিলাম। এ সময় তিনি বললেন, এমন একটি গাছ আছে যা মুসলিম লোকের ন্যায়, যার পাতা কখনো ঝরে পড়ে না, গাছটি কি গাছ তোমরা কি আমাকে বলতে পার? ইবরাহীম ইবনু সুফইয়ান (রহঃ) বলেন, সম্ভবতঃ ইমাম মুসলিম (রহঃ) বলেছেন, وَتُؤْتِي أُكُلَهَا كُلَّ حِينٍ যা প্রত্যেক মৌসুমে ফল প্রদান করে। তবে আমি ছাড়া অন্যান্যদের বর্ণনায়ও আমি পেয়েছি وَلاَ تُؤْتِي أُكُلَهَا كُلَّ حِينٍ অর্থাৎ- لاَ ছাড়া। ইবনু উমর (রাযিঃ) বলেন, আমার মনে হতে লাগল, তা হলো খেজুর গাছ। কিন্তু তখন আমি দেখলাম যে, আবূ বাকর ও উমর (রাযিঃ) কিছুই বলছেন না। তাই কোন কথা বা কিছু বলা আমার ভালো লাগলো না। কিন্তু উমার (রাযিঃ) এ কথা শুনে বললেন, যদি তুমি বলে দিতে তবে অমুক অমুক জিনিস লাভ করা হতেও আমি বেশি খুশী হতাম। (ইসলামিক ফাউন্ডেশন ৬৮৪২, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏ \"‏ أَخْبِرُونِي بِشَجَرَةٍ شِبْهِ أَوْ كَالرَّجُلِ الْمُسْلِمِ لاَ يَتَحَاتُّ وَرَقُهَا ‏\"‏ ‏.‏ قَالَ إِبْرَاهِيمُ لَعَلَّ مُسْلِمًا قَالَ وَتُؤْتِي أُكُلَهَا ‏.‏ وَكَذَا وَجَدْتُ عِنْدَ غَيْرِي أَيْضًا وَلاَ تُؤْتِي أُكُلَهَا كُلَّ حِينٍ ‏.‏ قَالَ ابْنُ عُمَرَ فَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ وَرَأَيْتُ أَبَا بَكْرٍ وَعُمَرَ لاَ يَتَكَلَّمَانِ فَكَرِهْتُ أَنْ أَتَكَلَّمَ أَوْ أَقُولَ شَيْئًا فَقَالَ عُمَرُ لأَنْ تَكُونَ قُلْتَهَا أَحَبُّ إِلَىَّ مِنْ كَذَا وَكَذَا ‏.‏","Ibn Umar reported:We were'in the company of Allah's Messenger (ﷺ) that he said: Tell me of a tree which has resemblance to a Muslim and the leaves of which do not wither. Ibrahim said that perhaps Imam Muslim had stated like this: It constantly bears fruit but I have, however, seen [It does not bear fruit constantly]. Ibn Umar said: It crossed my mind that it could be the date-palm tree, but as I saw Aba Bakr and Umar observe silence, I did not deem it fit that I should speak or I should say something. 'Umar said: Had you said so, it would have been dearer to me than such and such thing","আবূ বাকর ইবনু আবূ শাইবাহ (রহঃ) ..... ইবনু উমর (রাযিঃ",""],[7103,7103,"2812.01","উসমান ইবনু আবূ শাইবাহ ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... জাবির (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে শুনেছি, তিনি বলেন, আরব ভূখণ্ডে মুসল্লীগণ শাইতানের (শয়তানের) উপাসনা করবে, এ বিষয়ে শাইতান (শয়তান) নিরাশ হয়ে পড়েছে। তবে তাদের একজনকে অন্যের বিরুদ্ধে উসকিয়ে দেয়ার ব্যাপারে নিরাশ হয়নি। (ইসলামিক ফাউন্ডেশন ৬৮৪৩, ইসলামিক সেন্টার)","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ إِسْحَاقُ أَخْبَرَنَا وَقَالَ، عُثْمَانُ حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏ \"‏ إِنَّ الشَّيْطَانَ قَدْ أَيِسَ أَنْ يَعْبُدَهُ الْمُصَلُّونَ فِي جَزِيرَةِ الْعَرَبِ وَلَكِنْ فِي التَّحْرِيشِ بَيْنَهُمْ ‏\"‏ ‏.‏","Jabir reported:I heard Allah's Apostle (ﷺ) as saying: Verily, the Satan has lost all hopes that the worshippers would ever worship (him) in the peninsula of Arabia, but he (is hopeful) that he would sow the seed of dissension amongst them","উসমান ইবনু আবূ শাইবাহ ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... জাবির (রাযিঃ",""],[7104,7104,"2812.02","(…/...) আবু বাকর ইবনু আবু শাইবাহ, আবু কুরায়ব (রহঃ) ..... আ'মাশ (রহঃ) হতে এ সূত্রে অবিকল হাদীস বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮৪৪, ইসলামিক সেন্টার)","وَحَدَّثَنَاهُ أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعٌ، ح وَحَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ كِلاَهُمَا عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ ‏.‏","This hadith has been narrated on the authority of A'mash with the same chain of transmitters","",""],[7105,7105,"2813.01","উসমান ইবনু আবূ শাইবাহ ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... জাবির (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে শুনেছি। তিনি বলেন, নিশ্চয়ই ইবলীসের আরশ সমুদ্রের উপর স্থিরকৃত। সে লোকেদেরকে ফিতনায় নিপতিত করার উদ্দেশে তার বাহিনী পাঠায়। শাইতানের (শয়তানের) কাছে সবচেয়ে বড় সে-ই, যে সবচেয়ে বেশি ফিতনাহ সৃষ্টিকারী। (ইসলামিক ফাউন্ডেশন ৬৮৪৫, ইসলামিক সেন্টার)","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ إِسْحَاقُ أَخْبَرَنَا وَقَالَ، عُثْمَانُ حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏ \"‏ إِنَّ عَرْشَ إِبْلِيسَ عَلَى الْبَحْرِ فَيَبْعَثُ سَرَايَاهُ فَيَفْتِنُونَ النَّاسَ فَأَعْظَمُهُمْ عِنْدَهُ أَعْظَمُهُمْ فِتْنَةً ‏\"‏ ‏.‏","Jabir reported:I heard Allah's Messenger (way peace be upon him) as saying: The throne of Iblis is upon the ocean and he sends detachments (to different parts) inorder to put people to trial and the most important figure in his eyes is one who is most notorious in sowing the seed of dissension","উসমান ইবনু আবূ শাইবাহ ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... জাবির (রাযিঃ",""],[7106,7106,"2813.02","আবু কুরায়ব, মুহাম্মাদ ইবনুল আলী ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... জাবির (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ ইবলীস পানির উপর তার আরশ স্থাপন করতঃ তার বাহিনী প্রেরণ করে। তন্মধ্যে তার সর্বাধিক নৈকট্য অর্জনকারী সে-ই যে সবচেয়ে বেশী ফিতনাহ সৃষ্টিকারী। তাদের একজন এসে বলে, আমি অমুক অমুক কাজ করেছি। সে বলে, তুমি কিছুই করনি। অতঃপর অন্যজন এসে বলে, অমুকের সাথে আমি সকল প্রকার ধোকার আচরণই করেছি। এমনকি তার থেকে তার স্ত্রীকে আলাদা করে দিয়েছি। তারপর শাইতান (শয়তান) তাকে তার নিকটবর্তী করে নেয় এবং বলে হ্যাঁ, তুমি খুব ভাল। রাবী আ'মাশ বলেন, আমার মনে হয় তিনি বলেছেনঃ অতঃপর শাইতান (শয়তান) তার সাথে আলিঙ্গন করে। (ইসলামিক ফাউন্ডেশন ৬৮৪৬, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو كُرَيْبٍ، مُحَمَّدُ بْنُ الْعَلاَءِ وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ - وَاللَّفْظُ لأَبِي كُرَيْبٍ - قَالاَ أَخْبَرَنَا أَبُو مُعَاوِيَةَ، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ إِبْلِيسَ يَضَعُ عَرْشَهُ عَلَى الْمَاءِ ثُمَّ يَبْعَثُ سَرَايَاهُ فَأَدْنَاهُمْ مِنْهُ مَنْزِلَةً أَعْظَمُهُمْ فِتْنَةً يَجِيءُ أَحَدُهُمْ فَيَقُولُ فَعَلْتُ كَذَا وَكَذَا فَيَقُولُ مَا صَنَعْتَ شَيْئًا قَالَ ثُمَّ يَجِيءُ أَحَدُهُمْ فَيَقُولُ مَا تَرَكْتُهُ حَتَّى فَرَّقْتُ بَيْنَهُ وَبَيْنَ امْرَأَتِهِ - قَالَ - فَيُدْنِيهِ مِنْهُ وَيَقُولُ نِعْمَ أَنْتَ ‏\"‏ ‏.‏ قَالَ الأَعْمَشُ أُرَاهُ قَالَ ‏\"‏ فَيَلْتَزِمُهُ ‏\"‏ ‏.‏","Jabir reported that Allah's Messenger (ﷺ) said:Iblis places his throne upon water; he then sends detachments (for creating dissension) ; the nearer to him in rank are those who are most notorious in creating dissension. One of them comes and says: \"I did so and so.\" And he says: \"You have done nothing.\" Then one amongst them comes and says: \"I did not spare so and so until I sowed the seed of discord between a husband and a wife.\" The Satan goes near him and says: \"You have done well.\" A'mash said: He then embraces him","আবু কুরায়ব, মুহাম্মাদ ইবনুল আলী ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... জাবির (রাযিঃ",""],[7107,7107,"2813.03","(…) সালামাহ ইবনু শাবীব (রহঃ) ..... জাবির (রাযিঃ) থেকে বর্ণিত। তিনি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে বলতে শুনেছেন, শাইতান (শয়তান) তার সৈন্য বাহিনীকে পাঠিয়ে লোকেদেরকে ফিতনায় নিপতিত করে। তন্মধ্যে সে-ই তার নিকট সবচেয়ে বেশি মর্যাদার অধিকারী যে অধিক ফিতনাহ সৃষ্টিকারী। (ইসলামিক ফাউন্ডেশন ৬৮৪৭ ইসলামিক সেন্টার)","حَدَّثَنِي سَلَمَةُ بْنُ شَبِيبٍ، حَدَّثَنَا الْحَسَنُ بْنُ أَعْيَنَ، حَدَّثَنَا مَعْقِلٌ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏ \"‏ يَبْعَثُ الشَّيْطَانُ سَرَايَاهُ فَيَفْتِنُونَ النَّاسَ فَأَعْظَمُهُمْ عِنْدَهُ مَنْزِلَةً أَعْظَمُهُمْ فِتْنَةً ‏\"‏ ‏.‏","Jabir reported that Allah's Apostle (may peace be upqn him) said:The Satan sends detachments of his own in order to put people to trial and the highest in rank, in his eyes, is one who is most notorious in sowing the seed of dissension","…) সালামাহ ইবনু শাবীব (রহঃ) ..... জাবির (রাযিঃ",""],[7108,7108,"2814.01","উসমান ইবনু আবূ শাইবাহ ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... আবদুল্লাহ ইবনু মাসউদ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমাদের প্রত্যেকের সাথেই একটি শাইতান (শয়তান) নির্ধারিত আছে। সহাবাগণ প্রশ্ন করলেন, হে আল্লাহর রসূল! আপনার সাথেও কি? তিনি বললেন, হ্যাঁ, আমার সাথেও ৷ তবে তার মুকাবিলায় আল্লাহ আমাকে সাহায্য করেছেন। এখন আমি তার সম্পর্কে সম্পূর্ণরূপে নিরাপদ। এখন সে আমাকে কল্যাণকর বিষয় ছাড়া কক্ষনো অন্য কিছুর নির্দেশ দেয় না। (ইসলামিক ফাউন্ডেশন ৬৮৪৮, ইসলামিক সেন্টার)","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ إِسْحَاقُ أَخْبَرَنَا وَقَالَ، عُثْمَانُ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَا مِنْكُمْ مِنْ أَحَدٍ إِلاَّ وَقَدْ وُكِّلَ بِهِ قَرِينُهُ مِنَ الْجِنِّ ‏\"‏ ‏.‏ قَالُوا وَإِيَّاكَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَإِيَّاىَ إِلاَّ أَنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ فَلاَ يَأْمُرُنِي إِلاَّ بِخَيْرٍ ‏\"‏ ‏.‏","Abdullah b. Mas'ud reported that Allah's Messenger (ﷺ) said:There is none amongst you with whom is not an attache from amongst the jinn (devil). They (the Companions) said: Allah's Messenger, with you too? Thereupon he said: Yes, but Allah helps me against him and so I am safe from his hand and he does not command me but for good","উসমান ইবনু আবূ শাইবাহ ও ইসহাক ইবনু ইবরাহীম (রহঃ) ..... আবদুল্লাহ ইবনু মাসউদ (রাযিঃ",""],[7109,7109,"2814.02","ইবনুল মুসান্না, ইবনু বাশশার (রহঃ) ও আবু বকর ইবনু শাইবাহ (রহঃ) ..... মানসূর (রহঃ) এর সূত্রে জারীর থেকে অবিকল হাদীস বর্ণনা করেছেন। তবে সুফইয়ান (রহঃ) এর হাদীসের মধ্যে রয়েছে যে, প্রত্যেক মানুষের সাথে একটি শাইতান (শয়তান) সঙ্গীরূপে এবং একজন ফেরেশতা সঙ্গীরূপে নিযুক্ত রয়েছে। (ইসলামিক ফাউন্ডেশন ৬৮৪৯, ইসলামিক সেন্টার)","حَدَّثَنَا ابْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ قَالاَ حَدَّثَنَا عَبْدُ الرَّحْمَنِ، - يَعْنِيَانِ ابْنَ مَهْدِيٍّ - عَنْ سُفْيَانَ، ح وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا يَحْيَى بْنُ آدَمَ، عَنْ عَمَّارِ بْنِ رُزَيْقٍ، كِلاَهُمَا عَنْ مَنْصُورٍ، بِإِسْنَادِ جَرِيرٍ ‏.‏ مِثْلَ حَدِيثِهِ غَيْرَ أَنَّ فِي حَدِيثِ سُفْيَانَ ‏ \"‏ وَقَدْ وُكِّلَ بِهِ قَرِينُهُ مِنَ الْجِنِّ وَقَرِينُهُ مِنَ الْمَلاَئِكَةِ ‏\"‏ ‏.‏","This hadith has been narrated on the authority of Mansiir with the same chain of transmitters but with a slight variation of wording","",""],[7110,7110,"2815","হারূন ইবনু সাঈদ আল আইলী (রহঃ) ..... নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সহধর্মিণী আয়িশাহ সিদ্দীকা (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, কোন এক রজনীতে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার কাছ থেকে বের হলেন। তিনি বলেন, এতে আমার মনে কিছুটা অহমিকা আসল। তারপর তিনি এসে আমার অবস্থা অবলোকন করে বললেন, হে আয়িশাহ! তোমার কি হয়েছে? তুমি কি ঈর্ষাপরায়ণ হয়েছ? উত্তরে আমি বললাম, আমার ন্যায় মহিলা আপনার ন্যায় স্বামীর প্রতি কেন ঈৰ্ষাপরায়ণ হবে না? এ কথা শুনে রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেন, তোমার শাইতান (শয়তান) মনে হয় তোমার কাছে এসেছে? তখন তিনি বললেন, হে আল্লাহর রসূল! আমার সঙ্গেও কি শাইতান (শয়তান) রয়েছে? তিনি বললেন, হ্যাঁ, অবশ্যই। তারপর আমি বললাম, প্রত্যেক মানুষের সাথেই কি শাইতান (শয়তান) রয়েছে? তিনি বললেন, হ্যাঁ। অতঃপর আমি বললাম, হে আল্লাহর রসূল! আপনার সঙ্গেও কি রয়েছে? তিনি বললেন, হ্যাঁ, আমার সঙ্গেও। তবে আল্লাহ তা’আলা তার মুকাবিলায় আমাকে সাহায্য করেছেন। এখন তার ব্যাপারে আমি সম্পূর্ণরূপে নিরাপদ। (ইসলামিক ফাউন্ডেশন ৬৮৫০, ইসলামিক সেন্টার)","حَدَّثَنِي هَارُونُ بْنُ سَعِيدٍ الأَيْلِيُّ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي أَبُو صَخْرٍ، عَنِ ابْنِ، قُسَيْطٍ حَدَّثَهُ أَنَّ عُرْوَةَ حَدَّثَهُ أَنَّ عَائِشَةَ زَوْجَ النَّبِيِّ صلى الله عليه وسلم حَدَّثَتْهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم خَرَجَ مِنْ عِنْدِهَا لَيْلاً ‏.‏ قَالَتْ فَغِرْتُ عَلَيْهِ فَجَاءَ فَرَأَى مَا أَصْنَعُ فَقَالَ ‏\"‏ مَا لَكِ يَا عَائِشَةُ أَغِرْتِ ‏\"‏ ‏.‏ فَقُلْتُ وَمَا لِي لاَ يَغَارُ مِثْلِي عَلَى مِثْلِكَ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَقَدْ جَاءَكِ شَيْطَانُكِ ‏\"‏ ‏.‏ قَالَتْ يَا رَسُولَ اللَّهِ أَوَمَعِيَ شَيْطَانٌ قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ قُلْتُ وَمَعَ كُلِّ إِنْسَانٍ قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ قُلْتُ وَمَعَكَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ نَعَمْ وَلَكِنْ رَبِّي أَعَانَنِي عَلَيْهِ حَتَّى أَسْلَمَ ‏\"‏ ‏.‏","A'isha the wife of Allah's Apostle (ﷺ), reported that one day Allah's Messenger (ﷺ) came out of her (apartment) during the night and she felt jealous. Then he came and he saw me (in what agitated state of mind) I was. He said:A'isha, what has happened to you? Do you feel jealous? Thereupon she said: How can it be (that a woman like me) should not feel jealous in regard to a husband like you. Thereupon Allah's Messenger (ﷺ) said: It was your devil who had come to you, and she said: Allah's Messenger, is there along with me a devil? He said: Yes. I said: Is a devil attached to everyone? He said: Yes. I (Aisha) again said: Allah's Messenger, is it with you also? He said: Yes, but my Lord has helped me against him and as such I am absolutely safe from his mischief","",""],[7111,7111,"","(…/…) ইউনুস ইবনু আবদুল আ’লা আস্ সাদাকী (রহঃ) ... বুকায়র ইবনু আশাজ্জ (রহঃ) থেকে এ সূত্রে অবিকল হাদীস বর্ণনা করেছেন। তবে এতে بِرَحْمَةٍ مِنْهُ (তার করুণা) এর সঙ্গে وَفَضْلٍ (অনুগ্রহ) শব্দটিও উল্লেখ রয়েছে। কিন্তু তাতে سَدِّدُوا (সঠিক পন্থা অবলম্বন কর) শব্দটি বিদ্যমান নেই। (ইসলামিক ফাউন্ডেশন ৬৮৫১, ইসলামিক সেন্টার)","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا لَيْثٌ، عَنْ بُكَيْرٍ، عَنْ بُسْرِ بْنِ سَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ قَالَ ‏\"‏ لَنْ يُنْجِيَ أَحَدًا مِنْكُمْ عَمَلُهُ ‏\"‏ ‏.‏ قَالَ رَجُلٌ وَلاَ إِيَّاكَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَلاَ إِيَّاىَ إِلاَّ أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِرَحْمَةٍ وَلَكِنْ سَدِّدُوا ‏\"‏ ‏.‏ وَحَدَّثَنِيهِ يُونُسُ بْنُ عَبْدِ الأَعْلَى الصَّدَفِيُّ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، أَخْبَرَنِي عَمْرُو، بْنُ الْحَارِثِ عَنْ بُكَيْرِ بْنِ الأَشَجِّ، بِهَذَا الإِسْنَادِ غَيْرَ أَنَّهُ قَالَ ‏\"‏ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ ‏\"‏ ‏.‏ وَلَمْ يَذْكُرْ ‏\"‏ وَلَكِنْ سَدِّدُوا ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:None amongst you would attain salvation purely because of his deeds. A person said: Allah's Messenger, even you? Thereupon he said: Yes, not even I except that Allah wraps me in Mercy, but you should act with moderation. This hadith has been transmitted on the authority of Bukair b. al-Ashajj with a slight variation of wording","",""],[7112,7112,"","(…/…) ইউনুস ইবনু আবদুল আ’লা আস্ সাদাকী (রহঃ) ... বুকায়র ইবনু আশাজ্জ (রহঃ) থেকে এ সূত্রে অবিকল হাদীস বর্ণনা করেছেন। তবে এতে بِرَحْمَةٍ مِنْهُ (তার করুণা) এর সঙ্গে وَفَضْلٍ (অনুগ্রহ) শব্দটিও উল্লেখ রয়েছে। কিন্তু তাতে سَدِّدُوا (সঠিক পন্থা অবলম্বন কর) শব্দটি বিদ্যমান নেই। (ইসলামিক ফাউন্ডেশন ৬৮৫১, ইসলামিক সেন্টার)","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا لَيْثٌ، عَنْ بُكَيْرٍ، عَنْ بُسْرِ بْنِ سَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ قَالَ ‏\"‏ لَنْ يُنْجِيَ أَحَدًا مِنْكُمْ عَمَلُهُ ‏\"‏ ‏.‏ قَالَ رَجُلٌ وَلاَ إِيَّاكَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَلاَ إِيَّاىَ إِلاَّ أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِرَحْمَةٍ وَلَكِنْ سَدِّدُوا ‏\"‏ ‏.‏ وَحَدَّثَنِيهِ يُونُسُ بْنُ عَبْدِ الأَعْلَى الصَّدَفِيُّ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، أَخْبَرَنِي عَمْرُو، بْنُ الْحَارِثِ عَنْ بُكَيْرِ بْنِ الأَشَجِّ، بِهَذَا الإِسْنَادِ غَيْرَ أَنَّهُ قَالَ ‏\"‏ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ ‏\"‏ ‏.‏ وَلَمْ يَذْكُرْ ‏\"‏ وَلَكِنْ سَدِّدُوا ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:None amongst you would attain salvation purely because of his deeds. A person said: Allah's Messenger, even you? Thereupon he said: Yes, not even I except that Allah wraps me in Mercy, but you should act with moderation. This hadith has been transmitted on the authority of Bukair b. al-Ashajj with a slight variation of wording","",""],[7113,7113,"2816.03","কুতাইবাহ ইবনু সাঈদ (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তোমাদের মাঝে এমন কোন লোক নেই, যার আমল তাকে জান্নাতে দাখিল করাতে পারে। অতঃপর তাকে জিজ্ঞেস করা হলো, হে আল্লাহর রসূল! আপনিও কি নন? তিনি বললেন, হ্যাঁ আমিও নই। তবে আল্লাহ যদি তার অনুগ্রহ দ্বারা আমাকে আবৃত করে নেন। (ইসলামিক ফাউন্ডেশন ৬৮৫২, ইসলামিক সেন্টার)","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا حَمَّادٌ، - يَعْنِي ابْنَ زَيْدٍ - عَنْ أَيُّوبَ، عَنْ مُحَمَّدٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\"‏ مَا مِنْ أَحَدٍ يُدْخِلُهُ عَمَلُهُ الْجَنَّةَ ‏\"‏ ‏.‏ فَقِيلَ وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَلاَ أَنَا إِلاَّ أَنْ يَتَغَمَّدَنِي رَبِّي بِرَحْمَةٍ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:There is none whose deeds alone would entitle him to get into Paradise. It was said to him: And, Allah's Messenger, not even you? Thereupon he said: Not even I, but that my Lord wraps me in Mercy","কুতাইবাহ ইবনু সাঈদ (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ",""],[7114,7114,"2816.04","মুহাম্মাদ ইবনুল মুসান্না (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেন, তোমাদের মাঝে এমন কোন লোক নেই, যার আমল তাকে নাযাত দিতে পারে। সহাবাগণ জিজ্ঞেস করলেন, হে আল্লাহর রসূল! আপনিও কি নন? জবাবে তিনি বললেন, আমিও নই। তবে যদি আল্লাহ তা’আলা আমাকে তার মার্জনা ও করুণা দ্বারা ঢেকে নেন। রাবী ইবনু আওন (রহঃ) নিজ হাত দ্বারা নিজ মাথার দিকে ইশারা করে বললেন, আমিও না। হ্যাঁ, যদি আল্লাহ তা’আলা তার মার্জনা ও করুণা দ্বারা আমাকে ঢেকে ফেলেন। (ইসলামিক ফাউন্ডেশন ৬৮৫৩, ইসলামিক সেন্টার)","حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنِ ابْنِ عَوْنٍ، عَنْ مُحَمَّدٍ، عَنْ أَبِي، هُرَيْرَةَ قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ لَيْسَ أَحَدٌ مِنْكُمْ يُنْجِيهِ عَمَلُهُ ‏\"‏ ‏.‏ قَالُوا وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَلاَ أَنَا إِلاَّ أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِمَغْفِرَةٍ وَرَحْمَةٍ ‏\"‏ ‏.‏ وَقَالَ ابْنُ عَوْنٍ بِيَدِهِ هَكَذَا وَأَشَارَ عَلَى رَأْسِهِ ‏\"‏ وَلاَ أَنَا إِلاَّ أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِمَغْفِرَةٍ وَرَحْمَةٍ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:There is none amongst you whose deeds alone would attain salvation for him. They (the Companions) said: Allah's Messenger, not even you? He (the Holy Prophet) said: Not even I, but that Allah wraps me in Mercy and He grants me pardon. Ibn 'Aun pointed towards his head with his hand saying: Not even I, but that Allah wraps me in His Forgiveness and Mercy","মুহাম্মাদ ইবনুল মুসান্না (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ",""],[7115,7115,"2816.05","যুহায়র ইবনু হারব (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ এমন কোন লোক নই, যার আমল তাকে মুক্তি দিতে পারে। তারা বললেন, হে আল্লাহর রসূল! আপনিও কি নন? তিনি বলেন, আমিও নই। একমাত্র প্রত্যাশা এই যে, যদি আল্লাহ তা’আলা আমাকে তার করুণা দ্বারা সহায়তা করেন। (ইসলামিক ফাউন্ডেশন ৬৮৫৪, ইসলামিক সেন্টার)","حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرٌ، عَنْ سُهَيْلٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لَيْسَ أَحَدٌ يُنْجِيهِ عَمَلُهُ ‏\"‏ ‏.‏ قَالُوا وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَلاَ أَنَا إِلاَّ أَنْ يَتَدَارَكَنِيَ اللَّهُ مِنْهُ بِرَحْمَةٍ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:There is none whose deeds alone can'secure salvation for him. They said: Allah's Messenger, not even you? Thereupon he said: Not even I, but that, the Mercy of Allah should take hold of me","যুহায়র ইবনু হারব (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ",""],[7116,7116,"2816.06","(…) মুহাম্মাদ ইবনু হাতিম (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তোমাদের কারো আমল তাকে জান্নাতে প্রবেশ করাতে পারবে না। সহাবগণ বললেন, হে আল্লাহর রসূল! আপনিও কি নন? তিনি বললেনঃ আমিও নই। তবে যদি আল্লাহ তা’আলা আমাকে তাঁর অনুগ্রহ ও করুণা দ্বারা ঢেকে নেন। (ইসলামিক ফাউন্ডেশন ৬৮৫৫, ইসলামিক সেন্টার)","وَحَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، حَدَّثَنَا أَبُو عَبَّادٍ، يَحْيَى بْنُ عَبَّادٍ حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، حَدَّثَنَا ابْنُ شِهَابٍ، عَنْ أَبِي عُبَيْدٍ، مَوْلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لَنْ يُدْخِلَ أَحَدًا مِنْكُمْ عَمَلُهُ الْجَنَّةَ ‏\"‏ ‏.‏ قَالُوا وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَلاَ أَنَا إِلاَّ أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِفَضْلٍ وَرَحْمَةٍ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:None amongst you can get. into Paradise by virtue of his deeds alone. They said: Allah's Messenger, not even you? Thereupon he said: Not even I, but that Allah should wrap me in His Grace and Mercy","…) মুহাম্মাদ ইবনু হাতিম (রহঃ) ..... আবু হুরাইরাহ (রাযিঃ",""],[7117,7117,"2816.07","(…) মুহাম্মদ ইবনু আবদুল্লাহ ইবনু নুমায়র (রহঃ) .... আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমরা সঠিক পথে কায়িম থাকো এবং কমপক্ষে তার কাছাকাছি থাক। নিশ্চিতভাবে তোমরা জেনে রাখো, তোমাদের কেউ আমলের দ্বারা মুক্তি পাবে না। সহাবাগণ বললেন, হে আল্লাহর রসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম! আপনিও নন? তিনি বললেন, হ্যাঁ, আমিও নই। তবে আল্লাহ তা’আলা যদি স্বীয় রহমত ও অনুগ্রহ দ্বারা আমাকে ঢেকে রাখেন। (ইসলামিক ফাউন্ডেশন ৬৮৫৬, ইসলামিক সেন্টার)","حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ قَارِبُوا وَسَدِّدُوا وَاعْلَمُوا أَنَّهُ لَنْ يَنْجُوَ أَحَدٌ مِنْكُمْ بِعَمَلِهِ ‏\"‏ ‏.‏ قَالُوا يَا رَسُولَ اللَّهِ وَلاَ أَنْتَ قَالَ ‏\"‏ وَلاَ أَنَا إِلاَّ أَنْ يَتَغَمَّدَنِيَ اللَّهُ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ ‏\"‏ ‏.‏","Abu Huraira reported Allah's Messenger (ﷺ) as saying:Observe moderation in deeds (and if it is not possible, try to be near moderation) and understand that none amongst you can attain salvation because of his deeds alone. They said: Allah's Messenger, not even you? Thereupon he said: Not even I, but that Allah should wrap me in His Mercy and Grace","…) মুহাম্মদ ইবনু আবদুল্লাহ ইবনু নুমায়র (রহঃ) .... আবু হুরাইরাহ (রাযিঃ",""],[7118,7118,"2817.01","(…/২৮১৭) ইবনু নুমায়র (রহঃ) ..... জাবির (রাযিঃ) এর সানাদে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে অবিকল বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮৫৭, ইসলামিক সেন্টার)","وَحَدَّثَنَا ابْنُ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم مِثْلَهُ ‏.‏","This hadith has been narrated on the authority of Jabir through another chain of transmitters","",""],[7119,7119,"2817.02","(…/...) ইসহাক ইবনু ইবরাহীম (রহঃ) ..... আ'মাশ (রহঃ) এর সানাদে ইবনু নুমায়র (রহঃ) এর অবিকল বর্ণনা করেছেন। (ইসলামিক ফাউন্ডেশন ৬৮৫৮, ইসলামিক সেন্টার)","حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، بِالإِسْنَادَيْنِ جَمِيعًا كَرِوَايَةِ ابْنِ نُمَيْرٍ ‏.‏","A hadith like this has been narrated on the authority of A'mash through two other chains of transmitters. The wording is, however, the same","",""],[7120,7120,"2816.08","আবূ বাকর ইবনু আবূ শাইবাহ ও আবু কুরায়ব (রহঃ) ... আবু হুরাইরাহ (রাযিঃ) এর সানাদে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হতে অবিকল বর্ণনা করেছেন, তবে তাতে বর্ধিত আছে। অর্থাৎ- তোমরা সুসংবাদ গ্রহণ কর। (ইসলামিক ফাউন্ডেশন ৬৮৫৯, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ قَالاَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِهِ وَزَادَ ‏ \"‏ وَأَبْشِرُوا ‏\"‏ ‏.‏","This hadith has been narrated on the authority of Abu Huraira through another chain of transmitters with this addition:\" Give them glad tidings","",""],[7121,7121,"2817.03","সালামাহ্ ইবনু শাবীব (রহঃ) ..... জাবির (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম কে বলতে শুনেছি যে, তোমাদের কোন লোক তার আমল দ্বারা জান্নাতে প্রবেশ করতে পারবে না এবং জাহান্নাম থেকে মুক্তি পাবে না। আর আল্লাহর রহমত ব্যতীত আমি নিজেও বাঁচতে পারব না। (ইসলামিক ফাউন্ডেশন ৬৮৬০, ইসলামিক সেন্টার)","حَدَّثَنِي سَلَمَةُ بْنُ شَبِيبٍ، حَدَّثَنَا الْحَسَنُ بْنُ أَعْيَنَ، حَدَّثَنَا مَعْقِلٌ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏ \"‏ لاَ يُدْخِلُ أَحَدًا مِنْكُمْ عَمَلُهُ الْجَنَّةَ وَلاَ يُجِيرُهُ مِنَ النَّارِ وَلاَ أَنَا إِلاَّ بِرَحْمَةٍ مِنَ اللَّهِ ‏\"‏ ‏.‏","Jabir reported:I heard Allah's Apostle (ﷺ) as saying: None of you would get into Paradise because of his good deeds alone, and he would not be rescued from Fire, not even I, but because of the Mercy of Allah","সালামাহ্ ইবনু শাবীব (রহঃ) ..... জাবির (রাযিঃ",""],[7122,7122,"2818.01","ইসহাক ইবনু ইবরাহীম ও মুহাম্মাদ ইবনু হাতিম (রহঃ) ..... নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সহধর্মিণী আয়িশাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ মধ্যম পন্থা অবলম্বন কর, এর কাছাকাছি পথে থেকো এবং সুসংবাদ গ্রহণ কর, কারো আমলই তাকে জান্নাতে দাখিল করাতে পারবে না। সহাবাগণ জিজ্ঞেস করলেন, হে আল্লাহর রসূল! আপনিও কি নন? তিনি বললেন, আমিও নই। তবে হ্যাঁ, যদি আল্লাহ তা’আলা আমাকে তার রহমত দ্বারা ঢেকে নেন। তোমরা জেনে রাখো, নিয়মিত ‘আমলই আল্লাহর কাছে সবচেয়ে বেশী পছন্দের আমল, যদিও তা পরিমাণে কম হয়। (ইসলামিক ফাউন্ডেশন ৬৮৬১, ইসলামিক সেন্টার ৬৯১৮) হাসান আল হুলওয়ানী (রহঃ) ..... মূসা ইবনু উকবাহ (রাযিঃ) থেকে এ সূত্রে অবিকল হাদীস বর্ণনা করেছেন। কিন্তু তাতে তারা وَأَبْشِرُوا (সুসংবাদ গ্রহণ কর) শব্দটি বর্ণনা করেননি। (ইসলামিক ফাউন্ডেশন ৬৮৬২, ইসলামিক সেন্টার)","وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ، أَخْبَرَنَا مُوسَى بْنُ، عُقْبَةَ ح وَحَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، - وَاللَّفْظُ لَهُ - حَدَّثَنَا بَهْزٌ، حَدَّثَنَا وُهَيْبٌ، حَدَّثَنَا مُوسَى، بْنُ عُقْبَةَ قَالَ سَمِعْتُ أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، يُحَدِّثُ عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم أَنَّهَا كَانَتْ تَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ سَدِّدُوا وَقَارِبُوا وَأَبْشِرُوا فَإِنَّهُ لَنْ يُدْخِلَ الْجَنَّةَ أَحَدًا عَمَلُهُ ‏\"‏ ‏.‏ قَالُوا وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ قَالَ ‏\"‏ وَلاَ أَنَا إِلاَّ أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِرَحْمَةٍ وَاعْلَمُوا أَنَّ أَحَبَّ الْعَمَلِ إِلَى اللَّهِ أَدْوَمُهُ وَإِنْ قَلَّ ‏\"‏ ‏.‏","A'isha, the wife of Allah's Apostle (ﷺ), reported that Allah's Messenger (ﷺ) used to say:Observe moderation (in doing deeds), and if you fail to observe it perfectly, try to do as much as you can do (to live up to this ideal of moderation) and be happy for none would be able to get into Paradise because of his deeds alone. They (the Companions of the Holy Prophet) said: Allah's Messenger, not even you? Thereupon he said: Not even I, but that Allah wraps me in His Mercy, and bear this in mind that the deed loved most by Allah is one which is done constantly even though it is small","",""],[7123,7123,"2818.02","","وَحَدَّثَنَاهُ حَسَنٌ الْحُلْوَانِيُّ، حَدَّثَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ، بْنُ الْمُطَّلِبِ عَنْ مُوسَى بْنِ عُقْبَةَ، بِهَذَا الإِسْنَادِ وَلَمْ يَذْكُرْ ‏ \"‏ وَأَبْشِرُوا ‏\"‏ ‏.‏","This hadith has been narrated on the authority of Musa b. `Uqba with the same chain of transmitters and he did not make a mention of:\"Be happy","",""],[7124,7124,"2819.01","কুতাইবাহ্ ইবনু সাঈদ (রহঃ) ..... মুগীরাহ ইবনু শুবাহু (রাযিঃ) থেকে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এমনভাবে সালাত আদায় করেছেন যে, তার দু’পা ফুলে যেত। এ দেখে তাকে বলা হলো, আপনি এত কষ্ট করছেন কেন? আপনার তো পূর্বাপর যাবতীয় ত্রুটি-বিচ্যুতি মাফ করে দেয়া হয়েছে। এ কথার প্রত্যুত্তরে তিনি বললেন, আমি কি শুকরগুজার বান্দা হিসেবে পরিণত হব না? (ইসলামিক ফাউন্ডেশন ৬৮৬৩, ইসলামিক সেন্টার)","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، عَنِ الْمُغِيرَةِ بْنِ، شُعْبَةَ أَنَّ النَّبِيَّ صلى الله عليه وسلم صَلَّى حَتَّى انْتَفَخَتْ قَدَمَاهُ فَقِيلَ لَهُ أَتَكَلَّفُ هَذَا وَقَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ فَقَالَ ‏ \"‏ أَفَلاَ أَكُونُ عَبْدًا شَكُورًا ‏\"‏ ‏.‏","Mughira b. Shu'ba reported that Allah's Apostle (ﷺ) worshipped so much that his feet were swollen. It was said to him:(Why do you undergo so much hardship despite the fact that) Allah has pardoned for you your earlier and later sins? Thereupon he said: May I not (prove myself) to be a grateful servant (of Allah)?","কুতাইবাহ্ ইবনু সাঈদ (রহঃ) ..... মুগীরাহ ইবনু শুবাহু (রাযিঃ",""],[7125,7125,"2819.02","(…) আবু বকর ইবনু আবু শাইবাহ ও ইবনু নুমায়র (রহঃ) ..... মুগীরাহ ইবনু শুবাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সালাতে এমনভাবে দাঁড়িয়ে থাকতেন যে, এতে তার দু’পা ফুলে যেতো। এ দেখে সহাবাগণ বললেন, আল্লাহ তো আপনার আগের ও পরের যাবতীয় ত্রুটি-বিচ্যুতি মাফ করে দিয়েছেন। এ কথা শুনে তিনি বললেন, আমি কি শুকরগুজার বান্দা হব না? (ইসলামিক ফাউন্ডেশন ৬৮৬৪, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَابْنُ، نُمَيْرٍ قَالاَ حَدَّثَنَا سُفْيَانُ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، سَمِعَ الْمُغِيرَةَ بْنَ شُعْبَةَ، يَقُولُ قَامَ النَّبِيُّ صلى الله عليه وسلم حَتَّى وَرِمَتْ قَدَمَاهُ قَالُوا قَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ ‏.‏ قَالَ ‏ \"‏ أَفَلاَ أَكُونُ عَبْدًا شَكُورًا ‏\"‏ ‏.‏","This hadith has been transmitted on the authority of Mughira b. Shu'ba and the words are:Allah's Apostle (ﷺ) kept standing in prayer (for such long hours) that his feet were swollen. They (his Companions) said: Verily, Allah has pardoned for thee the earlier and the later of thine sins. Thereupon he said: Should I not prove myself to be a grateful servant (of Allah)?","…) আবু বকর ইবনু আবু শাইবাহ ও ইবনু নুমায়র (রহঃ) ..... মুগীরাহ ইবনু শুবাহ (রাযিঃ",""],[7126,7126,"2820","হারূন ইবনু মা’রূফ ও হারূন ইবনু সাঈদ আল আইলী (রহঃ) ..... আয়িশাহ্ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম যখন সালাত আদায় করতেন তখন এত বেশি দাঁড়িয়ে থাকতেন যে এতে তার দু’পা ফুলে যেত। এ দেখে আয়িশাহ্ (রাযিঃ) বললেন, হে আল্লাহর রসূল! আপনি এরূপ করছেন অথচ আপনার পূর্বাপর যাবতীয় ত্রুটি-বিচ্যুতি মাফ করে দেয়া হয়েছে। এ কথা শুনে তিনি বললেন, হে ‘আয়িশাহ আমি কি শুকরগুজার বান্দা হব না? (ইসলামিক ফাউন্ডেশন ৬৮৬৫, ইসলামিক সেন্টার)","حَدَّثَنَا هَارُونُ بْنُ مَعْرُوفٍ، وَهَارُونُ بْنُ سَعِيدٍ الأَيْلِيُّ، قَالاَ حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي أَبُو صَخْرٍ، عَنِ ابْنِ قُسَيْطٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا صَلَّى قَامَ حَتَّى تَفَطَّرَ رِجْلاَهُ قَالَتْ عَائِشَةُ يَا رَسُولَ اللَّهِ أَتَصْنَعُ هَذَا وَقَدْ غُفِرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ فَقَالَ ‏ \"‏ يَا عَائِشَةُ أَفَلاَ أَكُونُ عَبْدًا شَكُورًا ‏\"‏ ‏.‏","A'isha reported that when Allah's Messenger (ﷺ) occupied himself in prayer, he observed such a (long) qiyam (posture of standing in prayer) that his feet were swollen. A'isha said:Allah's Messenger you do this (in spite of the fact) that your earlier and later sins have been pardoned for you? Thereupon, he said. A'isha should I not prove myself to be a thanksgiving servant (of Allah)?","হারূন ইবনু মা’রূফ ও হারূন ইবনু সাঈদ আল আইলী (রহঃ) ..... আয়িশাহ্ (রাযিঃ",""],[7127,7127,"2821.01","আবূ বাকর ইবনু আবূ শাইবাহ, ইবনু নুমায়র (রহঃ) ..... শাকীক (রহঃ) থেকে বর্ণিত। তিনি বলেন, আবদুল্লাহ (রাযিঃ) এর অপেক্ষায় আমরা তার (বাড়ীর) দ্বারপ্রান্তে বসা ছিলাম। এ সময় ইয়াযীদ ইবনু মুআবিয়াহ্ নাখাঈ (রহঃ) আমাদের পাশ দিয়ে অতিক্রম করতে লাগলেন। আমরা তাকে বললাম, আপনি তাকে আমাদের অবস্থানের সংবাদটি দিন। তিনি ভেতরে তার নিকট গেলেন। আমনি দেরী না করে আবদুল্লাহ (রাযিঃ) আমাদের সম্মুখে বেরিয়ে আসলেন। তারপর তিনি বললেন, তোমাদের অবস্থানের সংবাদ আমাকে পৌছানো হয়েছে। তবে তোমাদের কাছে আসতে এ জিনিসই আমাকে নিষেধ করেছে যে, আমি যেন তোমাদেরকে বিরক্ত না করে ফেলি। রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাদের উদ্দেশে নির্ধারিত দিনে উপদেশ দিতেন, আমাদের মধ্যে যাতে বিরক্ত ভাব সৃষ্টি না হয়। (ইসলামিক ফাউন্ডেশন ৬৮৬৬, ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعٌ، وَأَبُو مُعَاوِيَةَ ح وَحَدَّثَنَا ابْنُ نُمَيْرٍ، - وَاللَّفْظُ لَهُ - حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ شَقِيقٍ، قَالَ كُنَّا جُلُوسًا عِنْدَ بَابِ عَبْدِ اللَّهِ نَنْتَظِرُهُ فَمَرَّ بِنَا يَزِيدُ بْنُ مُعَاوِيَةَ النَّخَعِيُّ فَقُلْنَا أَعْلِمْهُ بِمَكَانِنَا ‏.‏ فَدَخَلَ عَلَيْهِ فَلَمْ يَلْبَثْ أَنْ خَرَجَ عَلَيْنَا عَبْدُ اللَّهِ فَقَالَ إِنِّي أُخْبَرُ بِمَكَانِكُمْ فَمَا يَمْنَعُنِي أَنْ أَخْرُجَ إِلَيْكُمْ إِلاَّ كَرَاهِيَةُ أَنْ أُمِلَّكُمْ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَتَخَوَّلُنَا بِالْمَوْعِظَةِ فِي الأَيَّامِ مَخَافَةَ السَّآمَةِ عَلَيْنَا ‏.‏","Shaqiq reported:We were sitting at the door of Abdullah (b. Mas'ud) waiting for him (to come out and deliver a sermon to us). It was at this time that there happened to pass by us Yazid b. Mu'awiya an-Nakha'i. We said: Inform him ('Abdullah b. Mas'ud) of our presence here. He went in and Abdullah b. Mas'ud lost no time in coming out to us and said: I was informed of your presence here but nothing hindered me to come out to you but the fact that I did not like to bore you (by stuffing your minds with sermons) as Allah's Messenger (ﷺ) did not deliver us sermon on certain days fearing that it might prove to be boring for us","আবূ বাকর ইবনু আবূ শাইবাহ, ইবনু নুমায়র (রহঃ) ..... শাকীক (রহঃ",""],[7128,7128,"2821.02","আবূ সাঈদ আল আশাজ্জ ও মিনজাব ইবনুল হারিস আত তামীমী, ইসহাক ইবনু ইবরাহীম ও আলী ইবনু খাশরাম (রহঃ), ইবনু আবূ উমর (রহঃ) ..... আমাশ (রহঃ) হতে এ সূত্রে অবিকল হাদীস বর্ণনা করেছেন। মিনজাব আরও উল্লেখ করেছেন যে, ইবনু মুসহির হতে। তিনি বলেন, আ'মাশ বলেছেন, ‘আমর ইবনু মুররাহ হতে, তিনি শাকীক হতে, তিনি আবদুল্লাহ হতে। (ইসলামিক ফাউন্ডেশন ৬৮৬৭ ইসলামিক সেন্টার)","حَدَّثَنَا أَبُو سَعِيدٍ الأَشَجُّ، حَدَّثَنَا ابْنُ إِدْرِيسَ، ح وَحَدَّثَنَا مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ، حَدَّثَنَا ابْنُ مُسْهِرٍ، ح وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، وَعَلِيُّ بْنُ خَشْرَمٍ، قَالاَ أَخْبَرَنَا عِيسَى، بْنُ يُونُسَ ح وَحَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، كُلُّهُمْ عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ ‏.‏ نَحْوَهُ ‏.‏ وَزَادَ مِنْجَابٌ فِي رِوَايَتِهِ عَنِ ابْنِ مُسْهِرٍ قَالَ الأَعْمَشُ وَحَدَّثَنِي عَمْرُو بْنُ مُرَّةَ عَنْ شَقِيقٍ عَنْ عَبْدِ اللَّهِ مِثْلَهُ ‏.‏","This hadith has been narrated on the authority of 'Abdullah through other chains of transmitters","",""],[7129,7129,"2821.03","ইসহাক ইবনু ইবরাহীম, ইবনু আবূ উমর (রহঃ) ..... ওয়ায়িল এর পিতা শাকীক (রহঃ) থেকে বর্ণিত। তিনি বলেন, আবদুল্লাহ (রাযিঃ) প্রত্যেক বৃহস্পতিবার দিন আমাদেরকে উপদেশ দিতেন। এক লোক তাকে বললেন, হে আবদুর রহমানের পিতা! আমরা আপনার কাছ থেকে হাদীস বর্ণনা শুনতে ভালো লাগে এবং ইচ্ছা পোষণ করি যে, আপনি আমাদের কাছে প্রত্যেক দিন হাদীস বর্ণনা করেন। এ কথা শুনে তিনি বললেন, এ কাজ হতে আমাকে যা বিরত রাখে তা হলো, আমি তোমাদেরকে বিরক্ত করা পছন্দ করি না, রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাদের অবস্থার প্রতি লক্ষ্য রেখে নির্ধারিত দিনে উপদেশ দিতেন, আমরা যাতে বিরক্ত না হই। (ইসলামিক ফাউন্ডেশন ৬৮৬৮, ইসলামিক সেন্টার)","وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، ح وَحَدَّثَنَا ابْنُ أَبِي عُمَرَ، - وَاللَّفْظُ لَهُ - حَدَّثَنَا فُضَيْلُ بْنُ عِيَاضٍ، عَنْ مَنْصُورٍ، عَنْ شَقِيقٍ أَبِي وَائِلٍ، قَالَ كَانَ عَبْدُ اللَّهِ يُذَكِّرُنَا كُلَّ يَوْمِ خَمِيسٍ فَقَالَ لَهُ رَجُلٌ يَا أَبَا عَبْدِ الرَّحْمَنِ إِنَّا نُحِبُّ حَدِيثَكَ وَنَشْتَهِيهِ وَلَوَدِدْنَا أَنَّكَ حَدَّثْتَنَا كُلَّ يَوْمٍ ‏.‏ فَقَالَ مَا يَمْنَعُنِي أَنْ أُحَدِّثَكُمْ إِلاَّ كَرَاهِيَةُ أَنْ أُمِلَّكُمْ ‏.‏ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَتَخَوَّلُنَا بِالْمَوْعِظَةِ فِي الأَيَّامِ كَرَاهِيَةَ السَّآمَةِ عَلَيْنَا ‏.‏","Shaqiq b. Wi'il reported that 'Abdullah used to give us sermon on every Thursday. A person said:Abu 'Abd al-Rahman, we love your talk and so we yearn (to listen to you) and earnestly desire that you should deliver us lecture every day. Thereupon he said: There is nothing to hinder me in giving you talk (every day) but the fact that you may be bored. Allah's Messenger (ﷺ) did not deliver sermons on certain days (fearing that we might be bored)","ইসহাক ইবনু ইবরাহীম, ইবনু আবূ উমর (রহঃ) ..... ওয়ায়িল এর পিতা শাকীক (রহঃ",""]];
